#!/usr/bin/env python3
"""Every sentence on a surface has to agree with the policy this tree ships.

`scripts/three-surfaces.sh` holds the limitation list, the README and the site to each other, and
it was green on 2026-09-15 over four faults at once, because each of them said the same wrong thing
on every surface. The site called the width of a receipt outside-vouched while every receipt this
code issues rests on its own model. Five places called a machine that reaches only Roughtime seconds
wide while the operator floor refuses it. The list said the shipped default refuses over 250 ms while
the one-shot command signed up to 30 s. A twin can only tell you the copies match. This reads the
policy off the code and asks each sentence whether it contradicts it.

    python3 scripts/policy-sentences.py                 this tree, and the site beside it
    python3 scripts/policy-sentences.py --no-site       this tree alone, said on purpose
    python3 scripts/policy-sentences.py --site <url>    this tree, and the pages a running site serves
    python3 scripts/policy-sentences.py --self-test     seeds per rule and per shape, each watched refused
    python3 scripts/policy-sentences.py --score FILE    what this refuses of a set it has not been fitted to
    python3 scripts/policy-sentences.py --prints FILE   the sentence prints to record when a set becomes fitted
    python3 scripts/policy-sentences.py --attributions [FILE]   record the generated subject grade for the register, and write it
    python3 scripts/policy-sentences.py FILE...         only the files named, for a copy of an old tree
    python3 scripts/policy-sentences.py --tree DIR --surfaces PATTERN   the claims in another tree, the app's

**The only number anybody may quote about this file comes from `--score` on a set whose sha256 was
frozen before this file was opened.** `--self-test` proves each seed is refused by the rule it is
there for, which is a different property and is not a score: the seeds are the material this file was
built around, so they say nothing about a sentence nobody here has seen. Five rebuilds in two days
each reported a jump, because each set became a seed the moment its misses became rules and the next
number was taken on material this file had already been shaped around.
`scripts/policy-sentences-fitted.txt` carries every set that has measured this one, and `--score`
refuses a fitted one outright. `scripts/policy-sentences-fitted-sentences.txt` carries the sentences of
every fitted set by print and by their words, so a fitted set is refused by what it says rather than by
the bytes of its file: the same words in any order, the same letters once spaces and punctuation are
gone, a sentence cut or two joined, and letters nine tenths alike, which is what a numbered item, a
trailing clause, an article deleted or a word swapped leaves behind. What it cannot see is a sentence
reworded past that, and the block above `EDITS_IN_A_LONG_SENTENCE` says why nothing made of words can.

Exit 0 where nothing contradicts the policy, 1 where something does, with the file and the sentence
named, and 2 where the policy could not be read off the code or a surface could not be read. A fact
this cannot find is a failure, and so is a surface that is missing, empty or short of the floor of
sentences it yields, because a check that has read nothing has agreed with nothing. The site beside
this tree is a surface: absent, it is a failure unless --no-site says its absence is deliberate. On
2026-09-15 an emptied README, a landing file set to {}, and the site not beside all passed.

What it reads off the code, and nothing else:

- the operator floor, `min_operators` in `Policy::default`
- the agent's width ceiling, `max_bound_width` in `Policy::default`
- the one-shot command's ceiling, `CI_MAX_BOUND_WIDTH`, and the Action's `max-width` default, which
  have to be the same number
- how many operators stand behind the published Roughtime servers
- how many kinds of time source have a client, counted as `impl TimeSource for` anywhere under
  `crates/sources/src`
- whether anything outside the tests issues a receipt resting on outside signatures
- whether anything ships that lowers the floor, and whether a refusal receipt exists
- which kinds those are, by the file each client sits in, so a protocol named as having a client
  when no file carries one is refused by name

Every one of those is held to the sentences. A sentence stating the floor, the Roughtime operator
count or the kind count wrongly is refused, and so is one saying the Roughtime-only round is signed,
that the floor can be lowered, that outside evidence backs the width, that a refusal receipt exists,
or a ceiling or a max-width default that is not the code's. Each rule is written for the claim rather
than for one wording of it: a number in digits or in words, the verb in any of its forms, and the
passive as well as the active. Until the evening of 2026-09-15 three of the facts were read and held
nothing, and each of the other shapes was matched on the one sentence it was written from, so "at
least two operators" and "the outside signatures back up the width" passed on every surface.

What it refuses on principle, because the fact is the design and not a number in the code. Until
2026-09-16 every rule here held a sentence to a value read off the tree, and two independent test
passes that day refused 7 of 24 and 5 of 29 fresh sentences: "Our clock is accurate to the
millisecond", "TimeWitness prevents a backdated build from being published", "averages the readings
from all its sources" and "receipts carry legal weight under eIDAS" all passed, because nothing here
had a rule for them. Four claims are now refused wherever a clause asserts them and does not deny
them: accuracy where the product has resolution, our own bound presented as outside evidence or NTS
as evidence of any kind, enforcement of anything beyond declining to sign, and readings averaged into
a time. The fifth, legal weight or compliance, was held the same way until 2026-09-25 and is now a
closed list, in the paragraph after next. Each is written as the claim rather than as a wording of it: a
list of the words the claim turns on, the clause each word sits in, and one test of whether that
clause asserts or denies it. The clause is what the denial is scoped to, so "No regulation we have
checked, including A, B and C, requires clock accuracy" is one denial and "It refuses to sign, so it
prevents the build" is a denial and then a claim.

What a cold reader found on 2026-09-16, and what changed for it. Two sentence sets written from the
the rules of what this product may say, before this file was opened, were refused 26 of 45 and 22 of 45 while three sets whose
misses had been folded in scored 45, 35 and 42, so the seeds were measuring the seeds. The eight
classes they found are rules now, and each is written as the class rather than the sentence: the
three millisecond figures rule 1 of what this product may say names as somebody else's, and the two the simulated harness
produced, are refused beside a first-person subject without the attribution; accuracy as a bare noun
with a positive predicate, as ours, or as a thing delivered or guaranteed; Roughtime called a standard,
held to the standing its own client states; our own number said to be, to count as or to be treated as
evidence of any kind, whatever verb links them; each evidence role held to the direction it proves; the
gating verbs when negated, the neutral objects a CI gate acts on, and the noun forms of enforcement;
averaging by particle or by arithmetic; the verifiable delay function said to prove elapsed time; and
accreditation or qualified status claimed in the first person, where the phrase that let the honest
denial through had been letting the claim through too. The denial test changed shape with them: the
negated verb after a claim word has to be that word's own predicate, with no conjunction between,
so a trailing "and no hardware is required" denies nothing; `do`, `does` and `did` are denials; and
"nothing" counts only as the claim word's own object. Every set is fitted the moment its classes go
in, so the number that measures this file is the next cold set and never one of these.

What it cannot do. Metaphor: "your machine stops lying about the time" and "the door already shut"
say the forbidden thing in words no list carries. A negation of something else that sits before the
claim word in the same clause with no comma, "a stranger who trusts none of us can lean on the
servers' word that the bound is correct", is read as a denial. A pronoun standing for an outside
party, "they certify how far from UTC it could have been", names nothing this reads. And each rule's
honest register, the words that make a mention honest, is a list a writer could ride: "comes from
accreditation" beside a claim passed the claim, until the legal weight rule stopped having one.

The legal weight rule does not read a claim at all from 2026-09-25, because rule 6 of what this
product may say is held by it alone on the README, the list, the Action and the app, and twice that
day it was written to recognise the shapes a compliance claim takes and twice a test pass walked
round it within the hour: a claim after a semicolon, in the sentence after the rule, in the object of
the rule statement itself. So it fails closed. A paragraph that names any rule, regulation, standard,
statute or regulator, or any term of legal standing, passes only when it is word for word an entry in
`scripts/policy-sentences-legal-allowed.txt` for the surface it is on, spaces and quote marks aside.
The unit is the paragraph, because the claim does not have to sit in the sentence that names the
rule; every other rule still reads the sentence. Nothing else passes: not a denial, not a question,
not a true sentence nobody has read. The words that put a paragraph in scope are deliberately wider
than this product needs, because a paragraph wrongly in scope costs one entry and a claim let through
breaks that rule. From the night of 2026-09-25 they are read off the text as a person sees it: in any
case, through characters that draw nothing and letters of other alphabets that look Latin, spelled out
a letter at a time, and inside a web address; and they are read wherever a reader is shown words,
the list's version notes and every line the job summary writes included. Until then "Finra",
"eidas", a Cyrillic I in FINRA and a link to finra.org each passed on every surface. From 2026-09-26
the scope is read by kind as well as by name, because every set written blind had found the next
name the lists lacked: a run of capitals this product does not use itself, a standard's letters and
number, a body's name, a Latin tag, the words of the law in eight languages, and a letter of any
script these pages are not written in. The same day the job summary stopped being read from its
source: the script is run under bash, against a stand-in binary, once for each way it can end, and the
rule reads what it printed, because eight ways of writing a line in shell had put a claim in front of
a reader that a reader of source never saw. Later that day the source came back as a second reading
beside the runs rather than instead of them: a run reads only the paths it takes, and six claims on
one line with a test that ran were never printed. Every string the script and the Action's run
blocks hold is now read whether or not a run reaches it, and there is a run for each event, runner
and input value the script reads. What it still cannot see is a claim that names nothing in its scope at all:
"your clocks sit where the rules want them" names no rule, and a bare "rule" is in forty paragraphs
of the list about the agent's own rules, so it is not on the lists.

The claims on the site's two content files that copy the approved wording are held the other way
round from 2026-09-16, and not here. Every string those two files hand a reader has to cite an
approved claim through the `claimsUsed` binding the file carries, or be written down as not being
one with a reason, and `scripts/blocks-cite.mjs` in the site repository refuses the build
otherwise; the binding's own copy of each claim's status is held to the list it was copied from at
the product root, which neither repository can see. That is a closed world: about twenty claims,
each with its conditions written beside it, and a string outside it is refused whatever it says.
On those two files the rules above are therefore the second net and not the first. What neither
net reads is whether a bound block says what its claim says, and that residue is a human read over
the blocks the site check lists, which is a smaller read than every sentence on every surface.
The README, the limitation list, the verifier page, the Action and its summary carry no binding,
so on those the rules above are all that reads a claim, with the limits stated in the paragraph
before this one, and the open-world shape of those rules is why a cold set of fresh sentences
scored 28 of 45 against them on 2026-09-16 and why no longer list will close that gap.

Figures are the other way round and have been since 2026-09-16: deny by default, every quantity on
every surface read or refused by name. Until that day this half was allow by default too and nobody
had noticed, because the file's own docstring said so in a sentence that read as a boundary rather
than as a hole. "Ninety-nine percent of receipts come in under 12 milliseconds" invented a figure
this product has never measured, "TimeWitness bounds every stamp at 153.875 ms" and "Every stamp
carries an error bound of 128.7 ms" took real readings off one desktop on one afternoon and said
them of every stamp there will ever be, and all three went through untouched. A number is where rule
1 of what this product may say lives, and it is also where the line was drawn on 2026-09-09: prose
may be forward-looking and a number may not, because a reader will try to reproduce a number and
cannot try to reproduce a plan. A figure now has to be read by a rule, or refused for being said of
every stamp, or written down in `scripts/figures.json` with the conditions it was measured under and
said with a conditions word in its own sentence, or excused by name in `scripts/policy-figures.json`
with a reason written out. The walk, and what it deliberately
does not do, is at the block above `SEEDS`. It says how many figures it found and how each was
answered, so a growing excuse list is visible on a green run rather than only in a diff.
`tests/check-messaging-figures.py` at the product root is the other half and holds figures to the
artefacts they came from; this one holds them to having been read at all. From the afternoon of
2026-09-17 the register is held to its own evidence too: every entry names a receipt or a file in
this repository that states its figure, a receipt being decoded and read at the field the entry's
subject names, and an entry of a measurement names the machine and the path it was taken through,
so a desktop receipt given to a runner, a constant called measured, a history figure said in the
present and somebody else's figure said as measured by us are each refused naming the entry.

Served pages are read as text and as the attributes a reader is given without seeing the page: the
meta description, every alt, title and aria-label, and the page title. Until 2026-09-15 served mode
stripped attributes, so the sentence that called our width outside-vouched passed in an alt.
"""

import collections
import concurrent.futures
import hashlib
import html
import json
import os
import re
import shutil
import sys
import textwrap
import unicodedata
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SITE_BESIDE = ROOT.parent / 'timewitness-web' / 'content'

SURFACES = ['README.md', 'docs/what-timewitness-cannot-prove.md', 'docs/verifier.md', 'action.yml',
            'scripts/action-stamp.sh']
SITE_FILES = ['landing.json', 'cannot-prove.json', 'how-a-receipt-works.json', 'for-maintainers.json',
              'product-fixtures.json']
SITE_PAGES = ['/', '/cannot-prove', '/how-a-receipt-works', '/for-maintainers', '/screen']

# The receipt every surface points a reader at. What its outside signatures do is a fact the
# sentences are held to, read off the verifier rather than worked out here.
COMMITTED_RECEIPT = 'crates/verify/tests/data/a-real-stamp/receipt.cbor'

# The fewest sentences a surface can yield and count as read. The smallest surface, the Action's
# job summary, yields nineteen; an emptied file yields none.
SENTENCE_FLOOR = 5

# Keys in the site's content files whose own string is a note to whoever edits them and never
# reaches a page: an id, a source, a provenance line, an editor's note. The test is made against the
# key that holds the string and against nothing above it. Until 2026-09-16 it was made against every
# key on the way down, so `Note$` matched `commandNote` and pruned the whole object under it, and
# `install.commandNote.text`, which the front page prints under the install command, was not read: a
# dishonest sentence planted there exited 0 with the count unmoved at 1618, while the same sentence
# one key over exited 1. Two keys hold objects that are editorial in full and are named here rather
# than matched: `claimsUsed` is the binding of each served block to the approved claim it drew on,
# and `doNotSay` is the list of what not to say, so it is made of wrong sentences on purpose. Neither
# is served and neither is read here, and until 2026-09-16 that made this line the only place in
# either tree that knew the binding existed. It is checked now, by `scripts/blocks-cite.mjs` in the
# site repository, which refuses a served string the binding does not name; this line goes on
# saying only that the binding is not copy.
NOT_SERVED = re.compile(r'^\$|^src$|^id$|Note$|^provenance$|^departsFromSource$|^carriedLimit$|^note_?src$')
NOT_SERVED_OBJECTS = {'claimsUsed', 'doNotSay'}

WORDS = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8,
         'nine': 9, 'ten': 10, 'eleven': 11, 'twelve': 12, 'fifteen': 15, 'sixteen': 16, 'twenty': 20,
         'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'ninety': 90, 'hundred': 100,
         'a couple of': 2, 'a pair of': 2, 'half a dozen': 6, 'a dozen': 12, 'dozen': 12}
WORD = '(?:' + '|'.join(sorted(WORDS, key=len, reverse=True)) + ')'
# A count, in digits or in words, as sentences about operators and kinds write it.
COUNT = r'(?:\d+|' + WORD + r'|a single|single)'
# A duration's number, which can also be "a", "an", "a full", "half a", "a quarter of a" or
# "two hundred and fifty".
AMOUNT = (r'(?:\d+(?:\.\d+)?|half an?|a quarter of an?|a full|an?|' + WORD + r' hundred(?: and ' + WORD
          + r'(?:-' + WORD + r')?)?|' + WORD + r'(?:-' + WORD + r')?)')
UNIT = r'(ms|milliseconds?|s|seconds?|minutes?)'


class Unreadable(Exception):
    """The policy or a surface could not be read."""


def read(path):
    full = ROOT / path
    if not full.is_file():
        raise Unreadable(f'{path} is not there')
    return full.read_text(encoding='utf-8')


def block(text, opener):
    """The body of the first `{ ... }` after `opener`, braces counted."""
    start = text.find(opener)
    if start < 0:
        raise Unreadable(f'no "{opener}" to read')
    at = text.index('{', start)
    depth = 0
    for i in range(at, len(text)):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                return text[at + 1:i]
    raise Unreadable(f'"{opener}" never closes')


def constant_expression(expr, known):
    """A Rust constant expression of whole numbers, known names and multiplication, evaluated."""
    expr = re.sub(r'\bas\s+\w+', '', expr)
    value = 1
    for factor in expr.split('*'):
        factor = factor.strip().replace('_', '') if factor.strip().replace('_', '').isdigit() else factor.strip()
        if factor.isdigit():
            value *= int(factor)
        elif factor in known:
            value *= known[factor]
        else:
            raise Unreadable(f'"{factor}" in "{expr}" is not a number or a name this check knows')
    return value


def the_policy():
    """Everything the sentences are held to, read off the code."""
    policy = read('crates/clock/src/policy.rs')
    default = block(policy, 'impl Default for Policy')
    floor = re.search(r'min_operators:\s*(\d+)', default)
    agent = re.search(r'max_bound_width:\s*(\d+)\s*\*\s*NANOS_PER_(MILLI|SEC)', default)
    if not floor or not agent:
        raise Unreadable('Policy::default no longer sets min_operators and max_bound_width in a form this reads')
    per = {'MILLI': 10**6, 'SEC': 10**9}

    roughtime_core = read('crates/core/src/evidence/roughtime.rs')
    radius = re.search(r'pub const MIN_RADIUS_SECONDS: u32 = (\d+);', roughtime_core)
    if not radius:
        raise Unreadable('MIN_RADIUS_SECONDS is not where this reads it')
    # The client says at its head which document it implements and what standing that document has.
    # A sentence calling Roughtime an RFC or a standard is held to this line, and the day the draft is
    # published as one the line changes and this check stops reading until the rule below is revisited.
    standing = re.search(r'(Internet-Draft with intended status \w+), not an RFC', roughtime_core)
    if not standing:
        raise Unreadable('roughtime.rs no longer says what standing the specification it implements has')
    known = {'NANOS_PER_SEC': 10**9, 'NANOS_PER_MILLI': 10**6, 'NANOS_PER_MICRO': 10**3,
             'MIN_RADIUS_SECONDS': int(radius.group(1))}
    one_shot = re.search(r'const CI_MAX_BOUND_WIDTH: Nanos = ([^;]+);', read('crates/cli/src/stamp_cmd.rs'))
    if not one_shot:
        raise Unreadable('CI_MAX_BOUND_WIDTH is not where this reads it')
    one_shot_ns = constant_expression(one_shot.group(1), known)

    action = read('action.yml')
    max_width = re.search(r'\n  max-width:\n(?:    .*\n)*?    default: "(\d+)"', action)
    if not max_width:
        raise Unreadable('action.yml has no max-width input with a default this reads')

    names = re.findall(r'name:\s*"([^"]+)"', block(roughtime_core, 'pub fn published_keys()'))
    if not names:
        raise Unreadable('published_keys() names no Roughtime server this reads')
    overrides = dict(re.findall(r'server\.name == "([^"]+)"\s*\{\s*server\.operated_by\("([^"]+)"\)',
                                read('crates/sources/src/roughtime.rs')))
    operators = {overrides.get(n, '.'.join(n.split('.')[-2:])) for n in names}

    # Counted wherever the client sits under the crate, not only at its top level: on 2026-09-15
    # two clients moved one folder down and the count read one.
    sources = ROOT / 'crates' / 'sources' / 'src'
    if not sources.is_dir():
        raise Unreadable('crates/sources/src is not there, so the source kinds cannot be counted')
    kinds = sum(p.read_text(encoding='utf-8').count('impl TimeSource for') for p in sources.rglob('*.rs'))
    if kinds == 0:
        raise Unreadable('no "impl TimeSource for" anywhere under crates/sources/src, so the source kinds cannot be counted')

    # A receipt rests on outside signatures only where something sets that basis. The two files
    # allowed to name it are the one that reads and writes the word and the one that judges it.
    sandwich_setters = []
    for path in (ROOT / 'crates').glob('*/src/**/*.rs'):
        rel = path.relative_to(ROOT).as_posix()
        if rel in ('crates/receipt/src/schema.rs', 'crates/receipt/src/validate.rs'):
            continue
        if 'EpsilonBasis::ThirdPartySandwich' in path.read_text(encoding='utf-8'):
            sandwich_setters.append(rel)

    cli = ''.join(p.read_text(encoding='utf-8') for p in (ROOT / 'crates' / 'cli' / 'src').glob('*.rs'))
    inputs = re.findall(r'^  ([a-z-]+):\s*$', action.split('\noutputs:')[0], re.M)
    floor_lowerable = '--min-operators' in cli or any('operator' in i for i in inputs)
    # `Refusal` in the core crate is the return value a refusal is today, and not a receipt: nothing
    # signs it and nothing carries it anywhere. A receipt of one would be a type of its own.
    refusal_receipt = any(re.search(r'struct RefusalReceipt|fn refusal_receipt', p.read_text(encoding='utf-8'))
                          for p in (ROOT / 'crates').glob('*/src/**/*.rs'))
    # The kinds by name, from the file each client sits in: ntp.rs is NTP, roughtime.rs is Roughtime.
    kind_names = {p.stem.upper() if len(p.stem) <= 3 else p.stem.title()
                  for p in sources.rglob('*.rs') if 'impl TimeSource for' in p.read_text(encoding='utf-8')}

    # What the outside signatures of the receipt committed in this tree actually leave between them,
    # asked of the verifier a stranger runs. This is the one fact here that is not read out of the
    # source, and it is here because the surfaces make a claim about this receipt by name.
    #
    # It is also the fact that went stale in silence on 2026-09-19 and took six public surfaces with
    # it. The fix of that day stopped an authority's unstated accuracy being read as a nought, which is the
    # whole of the bracket on both authorities that ship, so the verifier stopped printing a span and
    # started saying that nothing outside bounds the moment from above. The README, the limitation
    # list and five served surfaces went on saying the signatures pin the moment to a few seconds,
    # and neither this file nor the site's figure check could see it: one recomputed the bracket
    # itself and the other only asked whether a number had its conditions beside it. Neither could
    # see a claim whose number had become none, because both of them read numbers.
    #
    # So the claim is held to the verdict rather than to a figure. While this answers none, a
    # sentence saying the outside signatures bracket, enclose or pin the moment is refused wherever
    # it is written, with or without a span beside it, and so is one giving a shipped authority the
    # not-later-than proof. The day an authority states an accuracy, or a reader's allowance ships
    # with one, this answers a number and the same sentences are allowed again.
    committed = ROOT / COMMITTED_RECEIPT
    if not committed.is_file():
        raise Unreadable(f'{COMMITTED_RECEIPT} is not there, so what its outside signatures bracket cannot be read')
    authorities = block(read('crates/core/src/evidence/rfc3161.rs'), 'pub fn published_authorities()')
    shipped_authorities = re.findall(r'name:\s*"([^"]+)"\.to_string\(\)', authorities)
    if not shipped_authorities:
        raise Unreadable('published_authorities() names no timestamp authority this reads')

    return {
        'floor': int(floor.group(1)),
        'agent_ns': int(agent.group(1)) * per[agent.group(2)],
        'one_shot_ns': one_shot_ns,
        'action_ns': int(max_width.group(1)),
        'roughtime_operators': len(operators),
        'roughtime_servers': len(names),
        'kinds': kinds,
        'kind_names': kind_names,
        'local_model_only': not sandwich_setters,
        'floor_lowerable': floor_lowerable,
        'refusal_receipt': refusal_receipt,
        'roughtime_standing': 'an ' + standing.group(1),
        'outside_bracket_ns': bracket_of(committed),
        'shipped_authorities': shipped_authorities,
    }


def words_of(text):
    return ' '.join(text.replace('**', '').replace('`', '').split())


PIECE_BREAK = re.compile(r'(?<=[.!?:;])\s+(?=[A-Z0-9])')
# A blank line is one holding nothing but spaces and tabs, which is what Markdown ends a paragraph on.
# Until 2026-09-25 any white space counted, so a line holding only a no-break space cut in two a
# paragraph the page shows as one, and a claim after it was read apart from the entry above it.
PARAGRAPH_BREAK = re.compile(r'\n[ \t\r\f\v]*\n')


def pieces(text):
    """The sentences every rule but the legal weight rule reads, cut after a full stop, a question
    mark, an exclamation mark, a colon or a semicolon wherever a capital or a digit follows."""
    out = []
    for paragraph in PARAGRAPH_BREAK.split(text):
        out += [s for s in PIECE_BREAK.split(words_of(paragraph)) if s]
    return out


def sentences(text):
    """What each rule is handed: the pieces above, except that a paragraph naming a rule, a
    regulation or anything of legal standing is handed over whole.

    A blank line ends a sentence whatever punctuation came before it, so the job summary's
    paragraphs and a content file's strings are read one at a time rather than run together into
    one sentence that names nothing when it is refused. The whole paragraph is the legal weight
    rule's unit because the claim does not have to sit in the sentence that names the rule. Cut at
    the semicolon, "FINRA 6820 requires business clocks synchronised to NIST time; TimeWitness keeps
    yours there." was a rule statement and then a sentence naming nothing, and both passed on every
    surface on 2026-09-25. Cut at the full stop, the same claim passes in two sentences. Every other
    rule still reads the pieces: `judge` cuts a whole paragraph back into them, so nothing another
    rule held to its own sentence is read across a paragraph instead.
    """
    out = []
    for paragraph in PARAGRAPH_BREAK.split(text):
        whole = words_of(paragraph)
        if not whole:
            continue
        out += [whole] if legal_terms(whole) else [s for s in PIECE_BREAK.split(whole) if s]
    return out


def markdown_text(text, list_file):
    # The version notes at the head of the limitation list are its history, and history is allowed
    # to quote what used to be true. Everything from the first heading down is the list itself.
    if list_file:
        at = text.find('\n## ')
        text = text[at:] if at >= 0 else text
    return text


def list_notes(text):
    """The version notes above the limitation list's first heading. Every rule but one leaves them
    alone, since history may quote what used to be true; the legal weight rule reads them, because
    no note is history about legal standing, and until 2026-09-25 a claim written under the title
    reached the published list unread."""
    at = text.find('\n## ')
    return text[:at] if at >= 0 else ''


def yaml_text(text):
    return '\n'.join(line.strip() for line in text.splitlines()
                     if not line.strip().startswith('#') and not line.strip().startswith('run:'))


# One line the script writes out: echo or printf, with its words in either kind of quote, and a
# redirect after them or none. Until 2026-09-25 only `echo "..."` alone on its line was read, so
# `echo '...'` and `echo "..." >> "$summary"` put words in the job summary that nothing read.
WRITTEN = re.compile(r'^\s*(echo|printf)(?:\s+-[neE]+)*(?:\s+(?:"((?:[^"\\]|\\.)*)"|\'([^\']*)\'))?'
                     r'\s*(?:\d?>>?&?\s*\S+\s*)?$')
HEREDOC = re.compile(r'<<-?\s*[\'"]?(\w+)[\'"]?')


def summary_text(text):
    # The job summary is written one echo a line and a bare echo between paragraphs, so the lines of
    # a paragraph are one text and a sentence that runs over a line break is read whole. Until
    # 2026-09-16 each echo was its own paragraph, and "enforcement path in this design." was read as a
    # sentence with its "there is no" on the line before. A here-document is read as the lines it
    # writes, and a printf as its format with the placeholders taken out.
    paragraphs, current = [], []
    lines = text.splitlines()
    n = 0
    while n < len(lines):
        line = lines[n]
        n += 1
        heredoc = HEREDOC.search(line)
        if heredoc and re.match(r'\s*cat\b', line):
            while n < len(lines) and lines[n].strip() != heredoc.group(1):
                if lines[n].strip():
                    current.append(lines[n].strip())
                else:
                    paragraphs.append(' '.join(current))
                    current = []
                n += 1
            n += 1
            continue
        m = WRITTEN.match(line)
        if not m:
            continue
        said = m.group(2) if m.group(2) is not None else m.group(3)
        if m.group(1) == 'printf' and said is not None:
            said = re.sub(r'%[-+ #0-9.]*[a-zA-Z%]|\\[nt]', ' ', said).strip()
            if not re.search(r'[A-Za-z]{2}', said):
                continue
        if said is None:
            if m.group(1) == 'echo':
                paragraphs.append(' '.join(current))
                current = []
        else:
            current.append(said)
    paragraphs.append(' '.join(current))
    return '\n\n'.join(p for p in paragraphs if p)


# The job summary as a reader is shown it, for the legal weight rule, from 2026-09-26.
#
# `summary_text` reads the script's source, and a reader of source is a reader of one shell grammar
# at a time. On 2026-09-26 eight ways of writing a line, an unquoted echo, quotes split round a word,
# printf with its words as an argument, a pipe to tee, a group, a line after `;` or `||` and echo -e
# among them, each put a claim naming FINRA 6820 in front of a reader and none was read. Growing the
# pattern for each would lose to the ninth. So the script is run instead: by bash, in a folder of its
# own, with a stand-in for the agent's binary that answers from fixed fields and touches no network,
# the job summary pointed at a file, and every word it writes read back from that file and from the
# log. Bash decides what a line prints, which is the one reading that cannot disagree with bash.
#
# A run reads only the lines it reaches, and a claim can sit in a branch a run does not take. So the
# script is run once for every way it can end, listed in SUMMARY_RUNS, with bash tracing which lines
# it ran, and a stretch of lines no run reached is held to the rule as it is written in the source: in
# scope and not word for word what some run printed, it is refused, because nobody has seen what it
# prints. What that cannot see is a claim assembled at run time, from pieces that name nothing, on a
# path none of the runs take. A new branch wants a new entry in SUMMARY_RUNS before it can say
# anything in scope.
#
# Every other rule still reads the source through `summary_text`, as it did, because a figure a run
# prints is the stand-in's figure and not the product's.
SUMMARY_SCRIPTS = {'action-stamp.sh'}
AS_SHOWN = ' as a run of it shows it'
NOT_REACHED = ' where no run of it reached'

# The stand-in for `timewitness`. It answers `stamp` by writing a file and `verify` with the fields
# the script reads, and TW_FIXTURE says which way it goes wrong, so each of the script's refusals is
# reached by one run.
STAND_IN = r'''#!/usr/bin/env bash
case "$1" in
stamp)
    out=
    while [ $# -gt 0 ]; do [ "$1" = --out ] && out="$2"; shift; done
    printf 'a stand-in receipt\n' > "$out"
    ;;
verify)
    case " $* " in
    *" --fields "*)
        [ "$TW_FIXTURE" = refused ] && exit 1
        for pair in earliest_ns=1000 latest_ns=2000 width_ns=1000 'width_in_words=one microsecond' \
                    reading_ns=1500 receipt_sha256=aa payload_hash=bb attestations_checked=1 \
                    attestations_carried=1 format_version=1; do
            [ "$TW_FIXTURE" = missing ] && [ "${pair%%=*}" = width_ns ] && continue
            printf '%s\n' "$pair"
        done
        [ "$TW_FIXTURE" = twice ] && printf 'width_ns=5\n'
        ;;
    *" --quiet "*)
        [ "$TW_FIXTURE" = silent ] && exit 0
        printf 'accepted, one of one attestations checked\nthe checked evidence holds the moment one microsecond wide\n'
        ;;
    esac
    ;;
esac
exit 0
'''

# Each way the script can end: the fixture the stand-in follows and the inputs the Action is given.
# Every path is relative to the run's own folder, so nothing a run prints carries the name of the
# machine's temporary folder, which is a different string on every machine and could itself hold a
# run of capitals. '{here}' is the folder the runs sit in.
SUMMARY_RUNS = [
    ('it signs', {}),
    ('it signs with every option', {'TW_PREVIOUS': '{here}/previous.cbor', 'TW_PROVENANCE': '{here}/provenance.json',
                                    'TW_IMAGE': 'an-image', 'TW_EVENT': 'release', 'TW_SEQUENCE': '2'}),
    ('there is no subject', {'TW_SUBJECT': '{here}/not-there'}),
    ('its verifier refuses it', {'TW_FIXTURE': 'refused'}),
    ('a field comes twice', {'TW_FIXTURE': 'twice'}),
    ('a field is missing', {'TW_FIXTURE': 'missing'}),
    ('the verifier says nothing', {'TW_FIXTURE': 'silent'}),
    ('the provenance is not there', {'TW_PROVENANCE': '{here}/not-there.json'}),
]

# What bash is told before the script: trace every line it runs into a file of its own, keep python3
# from being run, and send any web request nowhere.
PRELUDE = r'''
exec 7>"$TW_TRACE"
BASH_XTRACEFD=7
PS4='+@tw@${BASH_SOURCE[0]##*/}@${LINENO}@ '
python3() { :; }
set -x
source "$TW_SCRIPT"
'''


def a_bash():
    """The bash to run the script in, which on Windows is Git's and never the launcher Windows puts
    first on the path, since that one starts a Linux machine rather than a shell."""
    named = os.environ.get('TIMEWITNESS_BASH')
    if named:
        return named
    found = []
    git = shutil.which('git')
    if os.name == 'nt' and git:
        here = Path(git).resolve().parent
        for up in (here, here.parent, here.parent.parent):
            found += [up / 'bin' / 'bash.exe', up / 'usr' / 'bin' / 'bash.exe']
    if shutil.which('bash'):
        found.append(Path(shutil.which('bash')))
    for c in found:
        low = str(c).lower()
        if c.is_file() and not (os.name == 'nt' and ('system32' in low or 'windowsapps' in low)):
            return str(c)
    raise Unreadable('there is no bash here to run the job summary in, so what it writes was not read')


def what_a_run_shows(full, floor=SENTENCE_FLOOR):
    """What the summary script shows a reader, as (text shown, source lines no run reached).

    The text is every paragraph of the job summary and the log over all of SUMMARY_RUNS, each once.
    The lines are the stretches of the source, comments and blank lines aside, that no run ran and
    that are not word for word a line some run printed, each stretch joined into one paragraph."""
    import subprocess
    import tempfile
    source = full.read_text(encoding='utf-8').replace('\r\n', '\n')
    bash = a_bash()
    shown, ran, printed = [], set(), set()
    with tempfile.TemporaryDirectory(prefix='tw-summary-') as tmp:
        work = Path(tmp)
        script = work / 'the-summary-script.sh'
        script.write_text(source, encoding='utf-8', newline='\n')
        stand_in = work / 'action' / 'target' / 'release' / 'timewitness'
        stand_in.parent.mkdir(parents=True)
        stand_in.write_text(STAND_IN, encoding='utf-8', newline='\n')
        stand_in.chmod(0o755)
        for name in ('subject.bin', 'previous.cbor', 'provenance.json'):
            (work / name).write_text('{}\n' if name.endswith('.json') else 'a stand-in\n', encoding='utf-8')

        def one_run(n, label, inputs):
            here = work / f'run-{n}'
            here.mkdir()
            env = {k: v for k, v in os.environ.items() if not k.startswith(('GITHUB_', 'TW_', 'RUNNER_'))}
            env.update({'TW_SUBJECT': '../subject.bin', 'TW_ACTION_PATH': '../action', 'TW_OUTPUT': 'receipt.cbor',
                        'TW_KEY': 'agent.key', 'GITHUB_STEP_SUMMARY': 'summary.md', 'GITHUB_OUTPUT': 'output.txt',
                        'TW_TRACE': 'trace', 'TW_SCRIPT': '../' + script.name, 'HOME': '.', 'TMPDIR': '.',
                        'http_proxy': 'http://127.0.0.1:9', 'https_proxy': 'http://127.0.0.1:9',
                        'HTTP_PROXY': 'http://127.0.0.1:9', 'HTTPS_PROXY': 'http://127.0.0.1:9', 'no_proxy': ''})
            env.update({k: v.replace('{here}', '..') for k, v in inputs.items()})
            try:
                return here, subprocess.run([bash, '--noprofile', '--norc', '-c', PRELUDE], cwd=here, env=env,
                                            capture_output=True, timeout=120)
            except (OSError, subprocess.SubprocessError) as e:
                raise Unreadable(f'the job summary script could not be run ({label}): {e}') from e

        # The runs share nothing but the script and the stand-in, so they run side by side: one after
        # another they took twenty seconds on Windows, where every process bash starts is slow.
        runs = summary_runs(source)
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(RUN_WORKERS, len(runs))) as pool:
            done = list(pool.map(lambda job: one_run(job[0], *job[1]), enumerate(runs)))
        for n, (here, run) in enumerate(done):
            texts = []
            summary = (here / 'summary.md')
            texts.append(summary.read_bytes().decode('utf-8', 'replace') if summary.is_file() else '')
            texts += [run.stdout.decode('utf-8', 'replace'), run.stderr.decode('utf-8', 'replace')]
            if n == 0:
                if run.returncode != 0:
                    tail = texts[2].strip().splitlines()[-3:]
                    raise Unreadable(f'the job summary script exits {run.returncode} where it signs, so what it shows '
                                     f'was not read: {" | ".join(tail)}')
                count = len(pieces(texts[0].replace('\r\n', '\n')))
                if count < floor:
                    raise Unreadable(f'a run of {full.name} wrote {count} sentences to the job summary, under the floor '
                                     f'of {floor}, so it was not read')
            for text in texts:
                text = text.replace('\r\n', '\n')
                printed.update(line.strip() for line in text.splitlines() if line.strip())
                shown += [p for p in PARAGRAPH_BREAK.split(text) if p.strip()]
            trace = here / 'trace'
            if trace.is_file():
                for line in trace.read_bytes().decode('utf-8', 'replace').splitlines():
                    m = re.search(r'@tw@([^@]*)@(\d+)@', line)
                    if m and m.group(1) == script.name:
                        ran.add(int(m.group(2)))
    stretches, current = [], []
    for at, line in enumerate(source.splitlines(), start=1):
        bare = line.strip()
        if not bare or bare.startswith('#') or at in ran or bare in printed:
            if current:
                stretches.append(current)
                current = []
            continue
        current.append(bare)
    if current:
        stretches.append(current)
    unreached = [' '.join(s) for s in stretches]
    return '\n\n'.join(dict.fromkeys(words_of(p) for p in shown)), unreached


# The job summary as its source could write it, reached or not, from 2026-09-26.
#
# The runs above know a line was reached when bash traced it, and bash traces a line, not a command.
# On 2026-09-26 six claims naming FINRA 6820 passed because each sat on one line with a test that
# ran: a one-line if, a case, a `||`, a while, a trap. The test was traced, so the line counted as
# reached, and the echo after it never printed. Bash does print three of them under a scheduled
# event, a Windows runner or an input somebody sets, and no run here was either.
#
# So the source is read as well, and control flow plays no part in it. Every quoted string, every
# here-document body, and every word handed to a command, anywhere in the file and whether or not
# any run reaches it, is held to the legal weight rule as a line of the summary. The lines echo and
# printf write one after another are one paragraph, as they are in the summary, so a register entry
# written over several lines still reads whole. Beside a line's own words go the words it can come
# to when it runs, where the file says what they are: a string trap, eval or `bash -c` runs, a
# command substitution, printf's format filled from its arguments, an escape spelled out, a base64
# string decoded, and a variable given each value the file assigns it. Those are held to the rule
# where they name something the paragraph's own words do not, so one word is not refused twice.
#
# A word that is not prose, a path, a flag, a format with no words in it, falls out of scope by the
# same kind rules as everything else: a variable's name, a digest and a colour name nothing. What
# this still cannot read is a claim that exists only at run time from pieces the file names
# nowhere, such as one fetched over the network, and the runs are what read those.
SOURCE_READ = ' as its source could write it, reached or not'

SHELL_OPERATOR = re.compile(r';;&|;;|;&|&&|\|\||\|&|&>>|&>|<<<|<<-|<<|>>|>&|<&|>\||<>|[;&|()<>]')
# The reserved words after which bash expects a command, and the others.
SHELL_THEN_A_COMMAND = {'if', 'then', 'else', 'elif', 'while', 'until', 'do', '!', '{', '}', 'time', 'fi', 'done',
                        'esac'}
SHELL_RESERVED = SHELL_THEN_A_COMMAND | {'case', 'for', 'select', 'function', '[['}
SHELL_ASSIGNMENT = re.compile(r'^([A-Za-z_]\w*)(?:\[[^]]*\])?\+?=')
SHELL_WRITERS = {'echo', 'printf'}
SHELL_DECLARERS = {'local', 'declare', 'typeset', 'export', 'readonly'}
SHELL_REFERENCE = re.compile(r'\$\{[#!]?([A-Za-z_]\w*)|\$([A-Za-z_]\w*)')
PRINTF_SPEC = re.compile(r'%[-+ #0-9.*]*[a-zA-Z]')
BASE64_RUN = re.compile(r'[A-Za-z0-9+/]{16,}={0,2}')
SHELL_ESCAPE = re.compile(r'\\(x[0-9A-Fa-f]{1,2}|u[0-9A-Fa-f]{1,4}|U[0-9A-Fa-f]{1,8}|0[0-7]{0,3}|[1-7][0-7]{0,2}|.)', re.S)
SHELL_ESCAPED = {'n': '\n', 't': '\t', 'r': '\r', 'a': '\a', 'b': '\b', 'f': '\f', 'v': '\v', 'e': '\x1b', 'E': '\x1b'}
# How deep a string run as a command inside a string run as a command is read, and how many ways a
# line's variables are filled in. Both are far past anything the script does; they stop a file
# built to explode from hanging the check.
SHELL_DEPTH = 4
SHELL_VARIANTS = 64


def shell_unescape(text):
    """A string with its backslash escapes spelled out, as $'...', echo -e and printf write them."""
    def one(m):
        e = m.group(1)
        if e[0] in 'xuU' and len(e) > 1:
            try:
                return chr(int(e[1:], 16))
            except (ValueError, OverflowError):
                return m.group()
        if e[0].isdigit():
            return chr(int(e, 8) % 256)
        return SHELL_ESCAPED.get(e, e)
    return SHELL_ESCAPE.sub(one, text)


def _shell_quoted_end(src, i):
    """Where the quoted string opening at src[i] ends, one past its closing quote. An unclosed one
    runs to the end of the file, so what it holds is read rather than dropped."""
    n, q = len(src), src[i]
    if q == "'":
        j = src.find("'", i + 1)
        return n if j < 0 else j + 1
    j = i + 1
    while j < n:
        c = src[j]
        if c == '\\':
            j += 2
            continue
        if c == q:
            return j + 1
        if q == '"' and c == '$' and src[j + 1:j + 2] in ('(', '{'):
            j = _shell_closing(src, j + 1) + 1
            continue
        if q == '"' and c == '`':
            j = _shell_quoted_end(src, j)
            continue
        j += 1
    return n


def _shell_closing(src, i):
    """Where the bracket at src[i], ( or {, is closed, stepping over quotes; the end of the file where
    nothing closes it."""
    opening = src[i]
    closing = ')' if opening == '(' else '}'
    depth, n, j = 0, len(src), i
    while j < n:
        c = src[j]
        if c == '\\':
            j += 2
            continue
        if c in '\'"`':
            j = _shell_quoted_end(src, j)
            continue
        if c == opening:
            depth += 1
        elif c == closing:
            depth -= 1
            if depth == 0:
                return j
        j += 1
    return n


def _shell_double_quoted(body):
    """What bash makes of the inside of a double-quoted string, expansions left as written, and the
    commands substituted inside it."""
    out, inner, k, n = [], [], 0, len(body)
    while k < n:
        c = body[k]
        if c == '\\' and k + 1 < n:
            nxt = body[k + 1]
            if nxt == '\n':
                k += 2
                continue
            out.append(nxt if nxt in '$`"\\' else c + nxt)
            k += 2
            continue
        if c == '$' and body[k + 1:k + 2] in ('(', '{'):
            j = _shell_closing(body, k + 1)
            if body[k + 1] == '(':
                inner.append(body[k + 2:j])
            out.append(body[k:j + 1])
            k = j + 1
            continue
        if c == '`':
            j = _shell_quoted_end(body, k)
            inner.append(body[k + 1:j - 1])
            out.append(body[k:j])
            k = j
            continue
        out.append(c)
        k += 1
    return ''.join(out), inner


def _shell_word(src, i):
    """One shell word from src[i], as (end, what bash hands the command with expansions left as
    written, strings in it that bash may run as commands, array elements where it assigns an array)."""
    n, out, inner, elements = len(src), [], [], None
    while i < n:
        c = src[i]
        if c in ' \t\n;&|()<>':
            if c in '<>' and src[i + 1:i + 2] == '(':
                j = _shell_closing(src, i + 1)
                inner.append(src[i + 2:j])
                out.append(src[i:j + 1])
                i = j + 1
                continue
            if c == '(' and SHELL_ASSIGNMENT.match(''.join(out)) and ''.join(out).endswith('='):
                j = _shell_closing(src, i)
                elements = [w for w, _, _, _ in shell_words(src[i + 1:j])]
                out.append(' '.join(elements))
                i = j + 1
                continue
            break
        if c == '\\':
            if src[i + 1:i + 2] == '\n':
                i += 2
                continue
            out.append(src[i + 1:i + 2])
            i += 2
            continue
        if c == "'":
            j = _shell_quoted_end(src, i)
            literal = src[i + 1:j - 1] if src[j - 1:j] == "'" and j - 1 > i else src[i + 1:j]
            out.append(literal)
            inner.append(literal)
            i = j
            continue
        if c == '$' and src[i + 1:i + 2] == "'":
            j = i + 2
            while j < n and src[j] != "'":
                j += 2 if src[j] == '\\' else 1
            literal = shell_unescape(src[i + 2:j])
            out.append(literal)
            inner.append(literal)
            i = j + 1
            continue
        if c == '"' or (c == '$' and src[i + 1:i + 2] == '"'):
            if c == '$':
                i += 1
            j = _shell_quoted_end(src, i)
            body = src[i + 1:j - 1] if src[j - 1:j] == '"' and j - 1 > i else src[i + 1:j]
            text, subs = _shell_double_quoted(body)
            out.append(text)
            inner += [text] + subs
            i = j
            continue
        if c == '$' and src[i + 1:i + 2] in ('(', '{'):
            j = _shell_closing(src, i + 1)
            if src[i + 1] == '(':
                inner.append(src[i + 2:j])
            out.append(src[i:j + 1])
            i = j + 1
            continue
        if c == '`':
            j = _shell_quoted_end(src, i)
            inner.append(src[i + 1:j - 1])
            out.append(src[i:j])
            i = j
            continue
        out.append(c)
        i += 1
    return i, ''.join(out), inner, elements


def shell_items(src, first_line=1):
    """Every word of a piece of shell with the line it starts on and the part it plays, as
    (line, role, text, strings in it bash may run, array elements), and every here-document line as
    (line, 'body', text, [], None). The roles: 'name' for the command, 'reserved' for a reserved
    word, 'target' and 'fd' for a redirection's file and number, 'delimiter' for a here-document's,
    'assign' for an assignment, and 'word' for anything else a command is handed, a case's
    patterns among them."""
    items, pending = [], []
    n, i, line = len(src), 0, first_line
    command, expect = True, None
    # Each case still open, and where in it the next word is: its subject, a pattern, or a command.
    cases = []
    while i < n:
        c = src[i]
        if c == '\n':
            i += 1
            line += 1
            for delimiter, tabs in pending:
                while i < n:
                    end = src.find('\n', i)
                    end = n if end < 0 else end
                    text = src[i:end].lstrip('\t') if tabs else src[i:end]
                    i, at = min(end + 1, n), line
                    line += 1
                    if text == delimiter:
                        break
                    items.append((at, 'body', text, [], None))
            pending, command = [], True
            continue
        if c in ' \t\r':
            i += 1
            continue
        if c == '\\' and src[i + 1:i + 2] == '\n':
            i += 2
            line += 1
            continue
        if c == '#':
            end = src.find('\n', i)
            i = n if end < 0 else end
            continue
        op = SHELL_OPERATOR.match(src, i)
        if op and not (op.group() in '<>' and src[i + 1:i + 2] == '('):
            i = op.end()
            o = op.group()
            if o in ('<<', '<<-'):
                expect = ('delimiter', o == '<<-')
            elif o == '<<<':
                expect = 'here-string'
            elif o[-1] in '<>' or o in ('>&', '<&', '&>', '&>>', '>|', '<>'):
                expect = 'target'
            else:
                command = True
                if cases and cases[-1] == 'pattern' and o == ')':
                    cases[-1] = 'command'
                elif cases and cases[-1] == 'command' and o in (';;', ';&', ';;&'):
                    cases[-1] = 'pattern'
            continue
        at = line
        j, text, inner, elements = _shell_word(src, i)
        line += src.count('\n', i, j)
        if text.isdigit() and src[j:j + 1] in ('<', '>'):
            role = 'fd'
        elif isinstance(expect, tuple):
            pending.append((text, expect[1]))
            role, inner = 'delimiter', []
        elif expect == 'target':
            role = 'target'
        elif expect == 'here-string':
            role = 'word'
        elif cases and cases[-1] == 'subject':
            role = 'word'
            if text == 'in':
                cases[-1] = 'pattern'
        elif cases and cases[-1] != 'subject' and text == 'esac' and (command or cases[-1] == 'pattern'):
            role, command = 'reserved', False
            cases.pop()
        elif cases and cases[-1] == 'pattern':
            role = 'word'
        elif command and text in SHELL_RESERVED:
            role, command = 'reserved', text in SHELL_THEN_A_COMMAND
            if text == 'case':
                cases.append('subject')
        elif command and SHELL_ASSIGNMENT.match(text):
            role = 'assign'
        elif command:
            role, command = 'name', False
        else:
            role = 'word'
        expect = None
        items.append((at, role, text, inner, elements))
        i = j if j > i else i + 1
    return items


def shell_words(src):
    """Every word in a piece of shell, as `shell_items` gives them, the command's own name included."""
    return [(text, role, inner, elements) for _, role, text, inner, elements in shell_items(src)
            if role not in ('body', 'delimiter')]


def shell_assignments(items):
    """Each value the file gives a variable, by name: an assignment, a declaration, an array's
    elements, a for loop's list and printf -v."""
    values = collections.defaultdict(list)
    name_of = None
    previous = []
    for _, role, text, _, elements in items:
        if role == 'name':
            name_of, previous = os.path.basename(text), []
            continue
        if role == 'assign' or (role == 'word' and name_of in SHELL_DECLARERS):
            m = SHELL_ASSIGNMENT.match(text)
            if m:
                values[m.group(1)] += (elements or []) + [text[m.end():]]
        if role == 'word' and name_of == 'printf' and len(previous) >= 2 and previous[-2] == '-v':
            values[previous[-1]].append(PRINTF_SPEC.sub(' ', text))
        if role == 'word':
            previous.append(text)
    for k, (_, role, text, _, _) in enumerate(items):
        if role == 'reserved' and text in ('for', 'select') and k + 1 < len(items):
            loop = items[k + 1][2]
            for _, r, t, _, _ in items[k + 3:]:
                if r != 'word':
                    break
                values[loop].append(t)
    return {k: list(dict.fromkeys(v))[:8] for k, v in values.items()}


def shell_filled(text, values):
    """Each way a line's words read with its variables given the values the file assigns them."""
    ways = [text]
    for _ in range(8):
        grown = []
        for way in ways:
            names = [a or b for a, b in SHELL_REFERENCE.findall(way) if (a or b) in values]
            if not names:
                grown.append(way)
                continue
            name = names[0]
            pattern = re.compile(r'\$\{[#!]?' + name + r'(?:\[[^]]*\])?[^}]*\}|\$' + name + r'(?!\w)')
            grown += [pattern.sub(lambda _m, v=v: v, way) for v in values[name]]
        ways = list(dict.fromkeys(grown))[:SHELL_VARIANTS]
    return [w for w in ways if w != text]


def printf_filled(words):
    """printf's format with its arguments put where its conversions are, as far as the source says."""
    if not words:
        return ''
    fmt, args = words[0], list(words[1:])
    if not PRINTF_SPEC.search(fmt):
        return shell_unescape(fmt)
    rounds, out = 0, []
    while True:
        def one(m):
            if m.group().endswith('%'):
                return '%'
            return args.pop(0) if args else ''
        out.append(shell_unescape(PRINTF_SPEC.sub(one, fmt)))
        rounds += 1
        if not args or rounds > 8:
            return ' '.join(out)


def base64_said(text):
    """What any base64 run in a string decodes to, where it decodes to words."""
    import base64
    found = []
    for m in BASE64_RUN.finditer(text):
        run = m.group()
        run += '=' * (-len(run) % 4)
        try:
            said = base64.b64decode(run, validate=True).decode('utf-8')
        except (ValueError, UnicodeDecodeError):
            continue
        # Words, not bytes that happen to be printable: a sentence has spaces and is mostly letters.
        letters = sum(ch.isalpha() or ch == ' ' for ch in said)
        if ' ' in said.strip() and letters >= 0.8 * len(said) and all(ch.isprintable() or ch in '\n\t' for ch in said):
            found.append(said)
    return found


def shell_paragraphs(source, depth=0):
    """What a piece of shell could put in front of a reader, whatever runs, as a list of
    (paragraph, words it can come to at run time).

    A paragraph is the words of one source line, or of a run of lines each of which echo or printf
    writes, with a here-document's lines among them. A bare echo, a blank line of a here-document
    and any line doing something else end the run. Comments and blank lines are nothing."""
    items = shell_items(source)
    values = shell_assignments(items)
    lines = collections.OrderedDict()
    name_of, skip, fresh, handed = None, 0, False, None

    def entry(at):
        return lines.setdefault(at, {'words': [], 'writes': False, 'inner': [], 'printf': []})

    for at, role, text, inner, _ in items:
        e = entry(at)
        e['inner'] += inner
        if role == 'body':
            e['words'].append(text)
            e['writes'] = True
            continue
        if role == 'name':
            name_of, skip, fresh, handed = os.path.basename(text), 0, True, None
            if name_of in SHELL_WRITERS:
                e['writes'] = True
            if name_of == 'printf':
                handed = []
                e['printf'].append(handed)
            continue
        if role in ('reserved', 'target', 'fd', 'delimiter'):
            continue
        if role == 'assign':
            e['words'].append(text[SHELL_ASSIGNMENT.match(text).end():])
            continue
        # A word handed to a command. Echo's options, and printf's -v with the name it takes, are not
        # words anybody is shown.
        first, fresh = fresh, False
        if name_of == 'echo' and first and re.fullmatch(r'-[neE]+', text):
            fresh = True
            continue
        if name_of == 'printf' and (skip or text in ('-v', '--')):
            skip = 1 if text == '-v' else 0
            fresh = True
            continue
        if handed is not None:
            handed.append(text)
        if text in SHELL_WRITERS:
            e['writes'] = True
        e['words'].append(text)

    paragraphs, current, extra = [], [], []

    def close():
        if current:
            paragraphs.append((' '.join(current), list(extra)))
        current.clear()
        extra.clear()

    for at, e in lines.items():
        said = ' '.join(w for w in e['words'] if w.strip())
        more = []
        if said:
            more += shell_filled(said, values)
            if '\\' in said:
                more.append(shell_unescape(said))
            more += base64_said(said)
        for words in e['printf']:
            if words:
                more.append(printf_filled(words))
        if depth < SHELL_DEPTH:
            for piece in e['inner']:
                if piece.strip():
                    for p, m in shell_paragraphs(piece, depth + 1):
                        more += [p] + m
                    more += base64_said(piece)
        if e['writes'] and said:
            current.append(said)
            extra.extend(more)
            continue
        close()
        if said:
            paragraphs.append((said, more))
        elif more:
            paragraphs.append(('', more))
    close()
    return paragraphs


def run_blocks(text):
    """The shell of every `run:` in a workflow or an action's manifest, as a list of sources, a block
    scalar and a one-line value alike."""
    lines = text.splitlines()
    found, k = [], 0
    while k < len(lines):
        m = re.match(r'^(\s*)(-\s+)?run:\s*(.*?)\s*$', lines[k])
        if not m:
            k += 1
            continue
        parent = len(m.group(1))
        value = m.group(3)
        k += 1
        if re.fullmatch(r'[|>][-+0-9]*(?:\s+#.*)?', value):
            body = []
            while k < len(lines) and (not lines[k].strip() or len(lines[k]) - len(lines[k].lstrip()) > parent):
                body.append(lines[k])
                k += 1
            found.append(textwrap.dedent('\n'.join(body)))
        elif value.startswith("'") and value.endswith("'") and len(value) > 1:
            found.append(value[1:-1].replace("''", "'"))
        elif value.startswith('"') and value.endswith('"') and len(value) > 1:
            found.append(shell_unescape(value[1:-1]))
        else:
            found.append(value)
    return found


def what_the_source_could_write(text, name):
    """Every paragraph a shell script, or the run blocks of a manifest, could write, reached or not,
    with the words each can come to, for the legal weight rule."""
    sources = run_blocks(text) if name.endswith(('.yml', '.yaml')) else [text.replace('\r\n', '\n')]
    return [unit for source in sources for unit in shell_paragraphs(source)]


class Written(str):
    """A paragraph the source could write, carrying in `more` the words its lines can come to when
    they run. It is a string, so everything that reads a surface's units reads it as one."""
    more = ()


_TERMS = {}


def terms_of(text):
    """`legal_terms`, remembered, since a planted copy of the script is mostly the shipped one."""
    if text not in _TERMS:
        _TERMS[text] = tuple(legal_terms(text)) if text else ()
    return _TERMS[text]


def source_units(text, name):
    """The paragraphs `what_the_source_could_write` finds that the legal weight rule has anything to
    say about, as `Written` strings."""
    units = []
    for paragraph, more in what_the_source_could_write(text, name):
        if terms_of(paragraph) or any(terms_of(m) for m in dict.fromkeys(more)):
            unit = Written(paragraph)
            unit.more = tuple(dict.fromkeys(more))
            units.append(unit)
    return units


def source_faults(unit, where):
    """The legal weight rule over one paragraph the source could write and the words it can come to."""
    paragraph, more = str(unit), getattr(unit, 'more', ())
    found = legal_weight(paragraph, where) if terms_of(paragraph) else []
    named = set(terms_of(paragraph))
    for said in more:
        if set(terms_of(said)) - named:
            found += [f'{f} (as the line can come to at run time: "{words_of(said)[:160]}")'
                      for f in legal_weight(said, where)]
    return found

# The runs a job can be, past the ways the script ends, from 2026-09-26. A branch can wait on the
# event that started the workflow, on the runner's system or on an input somebody set, and until
# that day every run here went with all of those unset. So each variable the script reads gets runs
# of its own: every event GitHub names for the event, every system and architecture a runner
# reports for those, and for anything else, once set and once at each word the lines reading it hold
# it against. A value nothing in the script reads cannot change what it prints, so a variable the
# script never names gets no run, unless the script reads variables by a name it builds, lists them,
# or hands its text to eval or another file, and then every one gets its runs. Each run changes one
# thing, so a branch waiting on two at once is read only as its source, above.
GITHUB_EVENTS = ('branch_protection_rule', 'check_run', 'check_suite', 'create', 'delete', 'deployment',
                 'deployment_status', 'discussion', 'discussion_comment', 'fork', 'gollum', 'issue_comment', 'issues',
                 'label', 'merge_group', 'milestone', 'page_build', 'public', 'pull_request', 'pull_request_review',
                 'pull_request_review_comment', 'pull_request_target', 'push', 'registry_package', 'release',
                 'repository_dispatch', 'schedule', 'status', 'watch', 'workflow_call', 'workflow_dispatch',
                 'workflow_run')
RUNNER_VALUES = {'GITHUB_EVENT_NAME': GITHUB_EVENTS, 'RUNNER_OS': ('Linux', 'Windows', 'macOS'),
                 'RUNNER_ARCH': ('X86', 'X64', 'ARM', 'ARM64'), 'RUNNER_ENVIRONMENT': ('github-hosted', 'self-hosted'),
                 'RUNNER_DEBUG': ('1',), 'GITHUB_ACTIONS': ('true',), 'CI': ('true',)}
# What every run sets itself, so a run of its own for it would only break the run.
RUN_PINNED = {'TW_SUBJECT', 'TW_ACTION_PATH', 'TW_OUTPUT', 'TW_KEY', 'GITHUB_STEP_SUMMARY', 'GITHUB_OUTPUT', 'TW_TRACE',
              'TW_SCRIPT', 'HOME', 'TMPDIR', 'PATH', 'http_proxy', 'https_proxy', 'HTTP_PROXY', 'HTTPS_PROXY', 'no_proxy'}
# The commands that read a variable without its name written out, or run text as a script.
READS_ANY_VARIABLE = {'eval', 'env', 'printenv', 'compgen', 'source', '.', 'bash', 'sh'}
LISTS_VARIABLES = {'set', 'declare', 'typeset', 'export', 'readonly', 'local'}
# Most runs of bash at once. Past this, Windows spends the time starting processes.
RUN_WORKERS = 16


def summary_runs(source):
    """Every run the summary script is given: the ways it ends, then one run for each value of each
    variable it reads."""
    items = shell_items(source)
    read_on = collections.defaultdict(set)
    for at, _, text, _, _ in items:
        read_on[at] |= {a or b for a, b in SHELL_REFERENCE.findall(text)}
    held = collections.defaultdict(list)
    any_variable, case_of, command = False, None, None
    for k, (at, role, text, _, _) in enumerate(items):
        names = {a or b for a, b in SHELL_REFERENCE.findall(text)}
        if '${!' in text:
            any_variable = True
        if role == 'name':
            command = os.path.basename(text)
            following = items[k + 1][1] if k + 1 < len(items) else None
            if command in READS_ANY_VARIABLE or (command in LISTS_VARIABLES and (
                    following != 'word' or items[k + 1][2] == '-p')):
                any_variable = True
        if role == 'reserved' and text == 'case':
            case_of = set()
        elif role == 'reserved' and text == 'esac':
            case_of = None
        elif case_of is not None and not case_of and names:
            case_of = names
        for name in names:
            held[name]
        if role == 'word' and '$' not in text and text.strip() and not re.search(r'\s', text) and len(text) <= 40:
            word = text.strip('*?[]|')
            for name in read_on[at] | (case_of or set()):
                held[name].append(word)
    runs = list(SUMMARY_RUNS)
    given = {(k, v) for _, inputs in runs for k, v in inputs.items()}
    for name in sorted(set(held) | (set(RUNNER_VALUES) if any_variable else set())):
        if name in RUN_PINNED or not re.fullmatch(r'[A-Z][A-Z0-9_]*', name):
            continue
        words = list(RUNNER_VALUES.get(name, ())) + ['1'] + [w for w in held.get(name, ()) if w]
        for word in list(dict.fromkeys(words))[:len(RUNNER_VALUES.get(name, ())) + 8]:
            if (name, word) not in given:
                runs.append((f'with {name} {word}', {name: word}))
                given.add((name, word))
    return runs

def site_strings(node, key=''):
    if isinstance(node, dict):
        if node.get('name') == 'max-width' and 'default' in node:
            yield ('max-width input', f'max-width default {node["default"]} ns. {node.get("body", "")}')
        for k, v in node.items():
            if k in NOT_SERVED_OBJECTS:
                continue
            yield from site_strings(v, k)
    elif isinstance(node, list):
        for v in node:
            yield from site_strings(v, key)
    elif isinstance(node, str) and not NOT_SERVED.search(key):
        yield (key, node)


# What a served page says to a reader who is not shown the page: the description a search result
# quotes, the alt a screen reader speaks, a title or label a pointer shows.
#
# The lists are not written here. They are in `scripts/reader-contract.json` beside this file, which
# `scripts/pictures-say.mjs` in the site repository reads too, because until 2026-09-16 each check
# kept its own and they differed by one word. `aria-description` was in the picture reader and not in
# this one, so a rule-breaking sentence in that attribute was refused inside a picture and passed on
# the page around it. `tests/check-messaging-figures.py` at the product root holds the two to the
# contract, since it is the only one of the three that can see both repositories.
CONTRACT = json.loads((ROOT / 'scripts' / 'reader-contract.json').read_text(encoding='utf-8'))


def _alternatives(names):
    return '|'.join(re.escape(n) for n in names)


META_NAMES = _alternatives(CONTRACT['metaNames'])
# Single quotes as well as double. Next.js emits double, so the single-quoted form was latent rather
# than absent, and a check that is right only about the markup one generator happens to emit is a
# check about that generator.
QUOTED = r'(?:"([^"]*)"|\'([^\']*)\')'
ATTRIBUTE_TEXT = re.compile(r'<meta\b[^>]*\b(?:name|property)=[\'"](?:' + META_NAMES + r')[\'"][^>]*'
                            r'\bcontent=' + QUOTED + r'|<meta\b[^>]*\bcontent=' + QUOTED + r'[^>]*'
                            r'\b(?:name|property)=[\'"](?:' + META_NAMES + r')[\'"]|'
                            r'(?<![\w-])(?:' + _alternatives(CONTRACT['attributes']) + r')\s*=\s*' + QUOTED
                            + (r'|<title\b[^>]*>([^<]*)</title>' if CONTRACT['pageTitle'] else ''), re.I)


# A block element ends a sentence the way a blank line does in a content file, so the three items
# of a list on the front page are three sentences and not one. Until 2026-09-16 every tag became a
# space, and "signed evidence from independent outside parties of when it was taken Our own bound is
# labelled inside the receipt as our claim" was read as one sentence and refused, because the outside
# party of item three and the bound of the sentence after the list sat in one clause.
BLOCK_TAG = re.compile(r'</?(?:' + _alternatives(CONTRACT['blockElements']) + r')\b[^>]*>', re.I)


class Landed(urllib.request.HTTPRedirectHandler):
    """Keeps every hop a fetch took, so the fetch can refuse the ones that changed the page.

    `urlopen` follows a redirect and says nothing. Until 2026-09-16 nothing here compared where it
    landed with what it asked for, so a site answering 302 on all five paths was read as one page
    five times and the run exited 0 at 1,408 sentences with four fifths of the surface never
    opened. The sentence floor cannot catch that, because the page it lands on is a real page well
    over the floor.
    """

    def __init__(self):
        self.hops = []

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self.hops.append((req.full_url, newurl, code))
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def only_the_scheme(asked, landed):
    """True where two URLs differ by nothing but http becoming https.

    **The one redirect this check allows, and it is a deliberate call rather than an oversight.** An
    upgrade to https on the same host and the same path cannot change which page is read, so it is
    about the transport and not about the routing. Every other hop is refused, including a different
    path, a different host, a query appended, and https falling back to http.
    """
    a, b = urllib.parse.urlsplit(asked), urllib.parse.urlsplit(landed)
    return (a.scheme, b.scheme) == ('http', 'https') and a[1:] == b[1:]


def served_text(url):
    landed = Landed()
    opener = urllib.request.build_opener(landed)
    with opener.open(url, timeout=30) as response:
        page = response.read().decode('utf-8')
        final = response.geturl()
    for asked, to, code in landed.hops:
        if not only_the_scheme(asked, to):
            raise Unreadable(f'{asked} answered {code} to {to}, so the page read was not the page '
                             f'asked for. Only an upgrade of http to https on the same host and '
                             f'path is followed here')
    if final != url and not only_the_scheme(url, final):
        raise Unreadable(f'{url} was asked for and {final} was read')
    return page_text(page)


def page_text(page):
    """Everything a page gives a reader, by the contract beside this file.

    The words on it, with a block element ending a sentence the way a blank line does, and then the
    strings a reader is given without seeing the page: the description a search result quotes, the
    alt and the labels a screen reader speaks, the page title. Split out from the fetch on
    2026-09-16 so the self-test can hand it a page rather than stand a server up for one.
    """
    body = re.sub(r'(?is)<(script|style)\b.*?</\1>', ' ', page)
    spoken = [html.unescape(next(g for g in m.groups() if g is not None)) for m in ATTRIBUTE_TEXT.finditer(body)]
    text = html.unescape(re.sub(r'<[^>]+>', ' ', BLOCK_TAG.sub('\n\n', body)))
    return text + '\n\n' + '\n\n'.join(s for s in spoken if s.strip())


def number_of(token):
    """A count or an amount written in digits or in words, as a number."""
    token = token.strip().lower()
    if re.match(r'[\d.]+$', token):
        return float(token)
    if token in WORDS:
        return float(WORDS[token])
    if token in ('a', 'an', 'a single', 'single', 'a full'):
        return 1.0
    if token.startswith('half'):
        return 0.5
    if token.startswith('a quarter'):
        return 0.25
    hundreds = re.match(r'(\w+) hundred(?: and (.+))?$', token)
    if hundreds:
        return 100 * number_of(hundreds.group(1)) + (number_of(hundreds.group(2)) if hundreds.group(2) else 0)
    total = 0
    for part in token.split('-'):
        if part not in WORDS:
            raise ValueError(token)
        total += WORDS[part]
    return float(total)


def duration_ns(number, unit):
    return round(number_of(number) * {'ms': 10**6, 'millisecond': 10**6, 'milliseconds': 10**6,
                                      's': 10**9, 'second': 10**9, 'seconds': 10**9,
                                      'minute': 60 * 10**9, 'minutes': 60 * 10**9}[unit.lower()])


NEGATED_BEFORE = re.compile(r"\b(?:no|not|never|nothing|none|nor|cannot|without)\b|n't\b", re.I)
ROUGHTIME_ONLY = re.compile(r'\bonly\b[^.,;]{0,30}?\bRoughtime\b(?! signs)|Roughtime(?: servers?)? alone|'
                            r'cannot reach an NTP server', re.I)
PRESENT_SECONDS = re.compile(r'\b(?:is|are) seconds\b|\bseconds wide\b|\bstill reaches\b|\bSeconds is still\b|'
                             r'\bcan honestly (?:reach|do)\b|\bseconds on one\b|'
                             r'\babout [\d.]+ s where only\b', re.I)
# A Roughtime-only round said to be signed, in the forms that claim takes.
ROUGHTIME_SIGNED = re.compile(r'\bclears? the floor\b|\bis signed\b|\bgets? a receipt\b|\bstill signs\b|'
                              r'\bsigns anyway\b|\bis enough\b|\benough for a receipt\b|\bis accepted\b', re.I)
HISTORY = re.compile(r'refus|\bfloor\b|\bwould be\b|\bbefore 2026|\buntil 2026|\bhistory\b|\bno receipt\b|'
                     r'\bgets no\b|^Measured\b', re.I)
LOWERING = re.compile(r'\b(?:lower|drop|reduce|relax|override|change|turn down|set)(?:s|ing|ed)? (?:the|its|that|this|our) '
                      r'(?:operator |independence )?floor\b|'
                      r'\bfloor (?:can|may|could|might) be (?:lowered|dropped|reduced|relaxed|set|changed|overridden|configured)\b|'
                      r'\bfloor is (?:configurable|adjustable|a setting|an option|a flag|yours to set)\b|'
                      r'\bfloor\b[^.;]{0,30}?\b(?:was|were|is|has been|got|gets|will be) (?:reduced|lowered|dropped|cut|relaxed|'
                      r'changed|set|configured|turned down|overridden)\b|'
                      r'\bone line of configuration\b|--min-operators|\bmin-operators input\b', re.I)

# A clause ends at a semicolon, a colon, a bracket, a conjunction, or a comma followed by one. A bare
# comma does not end one, so "No regulation we have checked, including A, B and C, requires X" is one
# denial rather than four clauses with the "No" in the first, and "It refuses, so it prevents the
# build" is a denial and then a claim.
CLAUSE_BREAK = re.compile(r'[;:()|]|,\s*(?=(?:and|but|so|which|while|whereas|yet|because|although|though|whose|where|'
                          r'when|rather than|not|nor|thereby|therefore|hence|thus)\b)|'
                          r'(?<=\s)(?=(?:but|whereas|although|though|so that|thereby|therefore|hence|thus)\b)', re.I)
# What makes a clause a denial of the word the claim turns on: one of these before it in the clause,
# or a denial of it in the words after, per DENIED_AFTER below. "The third kind narrowed nothing", "An
# average of clocks is not a measurement" and "a compliance claim built on any of them would be
# false" are the second kind; "averages the readings from all its sources but not the outliers" is
# not one, because the "but" between the claim word and the negation means the negation is of
# something else.
DENIED_BEFORE = re.compile(r"^\W*(?:instead of|whether)\b|\b(?:no|not|never|nothing|none|nor|neither|cannot|without|refus\w*|declin\w*|"
                           r"rather than|far from|anything but|as opposed to|false|wrong|untrue|myth)\b|n't\b", re.I)
# The denial after the word has to be of that word. Until 2026-09-16 this was any negation inside a
# five-word window, and `and` and `but` were on its list of verbs, so "Certified microsecond accuracy
# ships with the standard agent and no hardware is required" was read as a denial of the accuracy,
# and one trailing selling point switched off four of the five claim rules. Now the words between the
# claim word and its verb may not include a conjunction, so the negated verb is the claim word's own
# predicate; `do`, `does` and `did` are on the list, because "AI Act Article 12 does not require
# tamper-evidence" is the sentence rule 6 of what this product may say wants written and it was refused; and "nothing" or
# "nobody" counts only as the claim word's own object, not as the subject of a following verb, so
# "narrowed nothing" is a denial and "evidence nobody has to trust us for" is not.
AUXILIARY = r"(?:is|are|was|were|be|being|been|remains?|does|do|did|has|have|had|can|could|will|would|shall|should|may|might|must)"
NOT_A_CONJUNCTION = r"(?!(?:and|but|or|so|which|whose|whom|that|because|when|while|if|where|since|although|though|whereas|as|unless|until)\b)"
DENIED_AFTER = re.compile(r"^\W*(?:" + NOT_A_CONJUNCTION + r"[\w'-]+\s+){0,5}?" + AUXILIARY + r"(?:\s+be)?(?:n't\b|\s+(?:not|never|no|nothing|false|wrong|untrue)\b)|"
                          r"^\W*(?:" + NOT_A_CONJUNCTION + r"[\w'-]+\s+){0,5}?(?:would|could|might) be\b[^.;,]{0,30}?\brather than\b|"
                          r"^\W*(?:(?:for|of|about|to|at|by|with|from|on|in)\s+)?(?:nothing|none|nobody|no one|no-one|neither)\b"
                          r"(?=\s*(?:$|[.,;:!?)]|(?:about|from|of|to|at|for|in|on|by|with|else|at all|whatever|more|further|beyond|but|and)\b))|"
                          r"^\W*(?:for|of|about|to|at|by|with|from|on|in)\s+no\b", re.I)
# A comma starts a new clause when what follows it has a subject or a verb of its own, and stays
# inside the clause when what follows is a list item or an aside: "No regulation we have checked,
# including A, B and C, requires X" is one denial and "Never mind the weather, our bound is third-party
# evidence" is an aside and then a claim.
NEW_CLAUSE = re.compile(r"\b(?:is|are|was|were|be|been|has|have|had|does|do|did|will|would|can|could|should|may|might|must|"
                        r"we|our|us|TimeWitness|it|its|they|their|you|your)\b", re.I)


def clause_around(sentence, at):
    """The span of the clause holding position `at`."""
    start, end = 0, len(sentence)
    for m in CLAUSE_BREAK.finditer(sentence):
        if m.end() <= at:
            start = m.end()
        elif m.start() > at:
            end = m.start()
            break
    return start, end


ANSWER = re.compile(r'^\W*(?:A: )?(?:No|Yes)[,.:;]\s*', re.I)


def same_clause(before):
    """The part of `before` from the last comma that starts a new clause, per NEW_CLAUSE."""
    start = at = 0
    for i, segment in enumerate(before.split(',')):
        if i and NEW_CLAUSE.search(segment):
            start = at
        at += len(segment) + 1
    return before[start:]


def denied_at(sentence, at, until, blank=None):
    """Whether the clause holding the span [at, until) denies it. `blank` is another span in the
    same clause whose words are not read for a negation, because they are the other half of the
    match: "not later than" in an evidence role is the role and not a denial."""
    c0, c1 = clause_around(sentence, at)
    before = sentence[c0:at]
    if blank and c0 <= blank[0] < at:
        before = before[:blank[0] - c0] + ' ' * (blank[1] - blank[0]) + before[blank[1] - c0:]
    before = ANSWER.sub('', before) if c0 == 0 else before
    return bool(DENIED_BEFORE.search(same_clause(before))) or bool(DENIED_AFTER.match(sentence[until:c1]))


def denied(sentence, match, group=0):
    """Whether the clause holding the word the claim turns on denies it."""
    at, until = match.span(group) if group and match.group(group) is not None else match.span()
    return denied_at(sentence, at, until)


def clauses(sentence):
    """The spans of the sentence's clauses."""
    cuts = [(m.start(), m.end()) for m in CLAUSE_BREAK.finditer(sentence)]
    starts = [0] + [end for _, end in cuts]
    ends = [start for start, _ in cuts] + [len(sentence)]
    return [(a, b) for a, b in zip(starts, ends) if b > a]


def denied_pair(sentence, c0, c1, first, second):
    """Whether the clause [c0, c1) denies a claim made of two spans in it. The later span is the
    word the denial is read against and the earlier is blanked out of the words before it."""
    a, b = (first, second) if first[0] <= second[0] else (second, first)
    return denied_at(sentence, b[0], b[1], blank=a)


# Outside parties, as the surfaces name them, and the width they may not be said to stand behind.
OUTSIDE = (r'(?:(?:outside|third.party|external|neutral|disinterested)\s+'
           r'(?:evidence|signatures?|parties|witnesses|attestations?|signers?|operators?|servers?|sources?)|'
           r'(?:independent|their|signed)\s+(?:evidence|signatures?|parties|witness(?:es)?|attestations?|signers?)|'
           r'(?:servers?|sources?|operators?|signers?)\'\s+(?:signatures?|word|say-so|names?)|independent (?:servers?|sources?)|'
           r'third parties|signers|strangers)')
OURS = (r'(?:(?:the|that|its|our|your|this|a receipt\'s|the receipt\'s) (?:whole |entire |stated |full |error |own )?(?:bound|width|interval|second number|claim|error margin|margin|'
        r'uncertainty|error bar)|how (?:wide|tight|narrow|big|small) (?:the|its|our|that) (?:bound|width|interval) (?:is|was)|'
        r'how far (?:from|off) UTC|how wrong (?:it|the clock|the reading) (?:could|might|may|can) (?:have )?be(?:en)?)')
# Each has one group, the word the claim turns on, and the clause around that word is what is read
# for a denial: "does not vouch for the bound" is the honest sentence and "who have never heard of us
# that supports it" is the fault. The seventh names no verb: until 2026-09-16 it listed the verbs an
# outside party could be said to do to the width, and "are what make the width believable" and "sign
# off on how wide the bound is" were not on the list. An outside party and our width in one clause,
# in that order and with nothing denying it, is the claim whatever verb carries it.
VOUCHING = [re.compile(p, re.I) for p in (
    r'evidence[^.;]{0,80}?\b(supporting|for) (?:that|the|its|this) (?:bound|width|second number|interval)\b',
    r'\b(vouch)(?:es|ing)? for (?:that|the|its|this) (?:second number|bound|width|interval)\b',
    r'evidence[^.;]{0,120}?\bthat (supports) it\b',
    r'\bhow wrong it could be,? and (proves) it\b',
    r'\breceipt anyone (can) check without trusting\b',
    r'\b(makes) the bound checkable\b',
    r'\b' + OUTSIDE + r'\b[^.;,]{0,60}?\b(' + OURS + r')\b',
    r'\b(?:bound|width|interval|second number)\b[^.;,]{0,25}?\b(?:is|are) (?:something|what|a (?:number|figure|thing)) '
    r'(?:the |that |those )?(' + OUTSIDE + r')\b',
    # A named signer said to stand behind the width, and the width said to be signed by one.
    r'\b(?:Roughtime|Cloudflare|Google|the (?:upstream |time |outside )?servers)\b(?: and \w+)?(?: servers?)? '
    r'((?:confirms?|attests?|vouch\w*|certif\w*|stands? behind|backs?|signs? off|underwrites?|guarantees?|verif\w*)\b[^.;,]{0,40}?'
    r'\b(?:bound|width|interval|margin|second number|uncertainty)\b)',
    r'\b(?:bound|width|interval|margin|second number)\b[^.;,]{0,30}?\b(?:is|are|was|were|gets?) ((?:counter)?signed by (?:[\w-]+ ){0,3}?'
    r'(?:Roughtime|NTS|NTP|servers?|sources?|operators?|signers?|third.part\w+|outside|independent|external|Cloudflare|Google)\b)',
    # The passive.
    r'\b(?:bound|width|interval|second number|claim|model)s?\b[^.;,]{0,30}?\b(?:is|are|was|were|gets?|has been|have been) '
    r'(?:[\w-]+ ){0,3}?((?:backed|supported|vouched for|underwritten|confirmed|attested|corroborated|proved|proven|verified|'
    r'guaranteed|certified|validated|endorsed|warranted|audited|signed off)(?: [\w-]+){0,3}? (?:by|from)\b)',
    # Our own number said to be, or to count as, outside evidence.
    r'\b(?:bound|width|interval|second number|model)s?\b[^.;,]{0,40}?\b(?:is|as|counts? as|serves? as|stands? as|amounts? to|'
    r'constitutes?|doubles? as|becomes?) (?:\w+[ ,-]+){0,3}?((?:outside|third.party|independent|external|portable|'
    r'stranger.checkable|neutral|signed|objective)[- ](?:evidence|proof|attestation))\b',
    # What a receipt is said to rest on, in the present tense. A bound "resting on" outside evidence
    # is the target the surfaces name and is not this.
    r'\b(?:receipts?|the (?:bound|width|interval|second number)|its (?:bound|width)|every receipt|each receipt)\b[^.;]{0,30}?'
    r'\b(rests?) on (?:the |its |their )?(?:third.party|outside|independent|external|signed|signers\'?)\b',
)]
# Outside signatures said to put a bracket round the moment, in the wordings the surfaces use for it:
# pinning it, bracketing it, enclosing it, or a bracket given as a span. Each has one group, the word
# the claim turns on, and the clause round that word is read for a denial, so "they bracket nothing"
# and "does not pin the moment" are the honest sentences and are not this.
#
# There is deliberately no subject in the first two. "They pin the moment the stamp was taken to a
# few seconds" carries its subject in the sentence before it, and a check that reads one sentence at
# a time would have let that one through on every surface it sits on. A bracketing verb with the
# moment as its object is the claim whoever is said to be doing it.
# The moment, in the words the surfaces use for it. "They pin when it was taken to 2 s" said the
# whole claim without the noun, and the first draft of the rule below read straight past it.
#
# The signing is the same moment in other words, and the app's front page said "they pin when it was
# signed" from 2026-09-14 to 2026-09-23 with this rule green, because it read taken and not signed.
# The verifier says the opposite on the receipt every surface points at: nothing outside it says when
# it was signed, only when its subject existed. A version 1 receipt can carry a witness over its own
# signature, and that one does say when it was signed, but its authority states no accuracy either,
# so it pins nothing in UTC.
MOMENT = (r'(?:the moment|the signing|when it was (?:taken|signed|made|issued)|when that reading was taken|'
          r'when (?:the|a|this|that) (?:reading|stamp|receipt|event|signature) was (?:taken|signed|made|issued))')
BRACKETING = [re.compile(p, re.I) for p in (
    r'\b(pins?|pinning|pinned|brackets?|bracketing|bracketed|encloses?|enclosing|enclosed|straddles?|straddling|'
    r'sandwiches|sandwiched)\b[^.;]{0,40}?\b' + MOMENT + r'\b',
    r'\b' + MOMENT + r'\b[^.;]{0,40}?\b(?:is|are|was|were|gets?|stays?|sits?) (?:\w+ ){0,2}?(pinned|bracketed|enclosed|'
    r'fixed from outside|held from outside)\b',
    r'\bsignatures?\b[^.;,]{0,40}?\b(enclose|encloses|enclosed|bracket|brackets|bracketed|pin|pins|pinned)\b',
    r'\b(?:to|in|inside|within|of) an? [^.;]{0,24}?\b(bracket)\b',
)]
# A named timestamp authority given the not-later-than proof. The role itself is defined on these
# surfaces and has to stay sayable, so this is scoped to an authority that ships: "An independent
# final witness proves not-later-than" is the design and is not held to anything, and "DigiCert
# signed for the payload hash, so the document existed no later than the moment its token states"
# is a claim about a token this product fetches and is.
NOT_LATER_PROVED = [re.compile(p, re.I) for p in (
    r'\b(proves?|proving|proved|establishes?|shows?|demonstrates?|gives? us|puts? a) [^.;]{0,20}?not.later.than\b',
    r'\b(?:existed|was made|was taken|was written|was created|happened|is) ((?:no|not) later than)\b',
    r'\b(bounds?|bounding|bounded|caps?|closes?|fixes?) (?:the |this |that )?moment from above\b',
)]
# The product's own phrase for a third party, which carries a "never" that negates nothing.
NEVER_HEARD = re.compile(r'\bwho (?:have|has) never heard of (?:us|this product)\b', re.I)
# A receipt said to be signed by anybody but the agent that issued it. The outside signatures inside a
# receipt are on the signers' own answers, and the receipt itself is signed by the agent's key.
RECEIPT_SIGNED_BY = re.compile(r'\breceipts?\b[^.;,]{0,30}?\b(?:(?:is|are|gets?|was|were|being) (?:counter)?signed by |'
                               r'(?:bears?|carr(?:y|ies)|holds?) the (?:counter)?signatures? of )('
                               r'(?:(?:the |its |their )?(?:Roughtime |NTS |NTP |public |time |upstream |outside )?(?:servers?|sources?|signers?|operators?|corridor)\b|Roughtime|NTS|NTP|'
                               r'(?:a |an |the )?(?:third.part\w+|outside|independent|external|neutral|public)\b))', re.I)
# NTS said to be evidence of any kind. Its keys are symmetric, so the machine holding one could
# compose the answer it then checks, and the receipt format refuses it in every evidence role.
NTS_EVIDENCE = re.compile(r'\bNTS\b[^.;]{0,80}?\b(evidence(?! role)|proof|attest\w*|portable|stranger|third.party|vouch\w*|'
                          r'verifiable|checkable|witness\w*)\b|'
                          r'\b(evidence(?! role)|proof|attest\w*|portable|stranger|third.party|vouch\w*|verifiable|checkable|witness\w*)\b'
                          r'[^.;]{0,80}?\bNTS\b', re.I)
# Our own number said to be, to count as, or to be treated as evidence, whatever kind of evidence
# and whatever verb links them. VOUCHING above needed the evidence to be called outside or
# third-party; "the interval is independently attested", "treat the agent's interval as the
# independent witness" and "our own bound are the same kind of proof" said it without that word.
OUR_NUMBER = r'(?:bound|width|interval|second number|model|reading|number|figure|error margin|uncertainty)s?'
OWN_AS_EVIDENCE = [re.compile(p, re.I) for p in (
    r'\b' + OUR_NUMBER + r'\b[^.;,]{0,40}?\b(?:is|are|as|counts? as|serves? as|stands? as|amounts? to|constitutes?|doubles? as|'
    r'becomes?|supplies|supply|provides?|carries|carry|generates?|makes?) (?:\w+[ -]+){0,4}?'
    r'((?:evidence|proof|attest\w*|witness\w*|vouched for|corroborated|underwritten|certified|notari[sz]ed|independently \w+))\b',
    r'\b(?:treat\w*|read|take|count|accept|regard|use)\b[^.;,]{0,30}?\b' + OUR_NUMBER + r'\b[^.;,]{0,20}?\bas (?:\w+ ){0,3}?'
    r'((?:evidence|proof|attestation|witness\w*))\b',
    r'\b(?:evidence|proof|attestation|witness\w*)\b[^.;,]{0,30}?\b((?:generated|produced|computed|written|issued|made|supplied|'
    r'provided|created|signed) by (?:our|the agent|us|TimeWitness|itself|the product|the receipt))\b',
    r'\b' + OUR_NUMBER + r'\b[^.;]{0,60}?\b((?:the )?same (?:kind|sort|class|type|grade|level|weight)(?: of)? '
    r'(?:evidence|proof|attestation|witness))\b',
    r'\b(self.signed (?:\w+ ){0,2}?(?:is|as|counts? as) (?:\w+ ){0,3}?(?:evidence|proof|attestation|witness))\b',
)]
# The three evidence roles, and the direction each one proves. A public freshness beacon proves
# not-earlier-than, because its value could not have been known before its round was published; an
# independent final witness, a timestamp authority, a transparency log or a public anchor, proves
# not-later-than, because it signed after the payload existed. A source given the other direction
# is refused: "the freshness beacon proves the stamp was not made later than it says" was passing
# on 2026-09-16 because nothing here knew which way each role points.
ROLE_SOURCE = {
    'freshness beacon': re.compile(r'\b(?:(?:freshness|public|randomness) )?beacons?\b|\bdrand\b|\bUChile\b', re.I),
    'final witness': re.compile(r'\bRFC ?3161\b|\bRFC ?9921\b|\btime.?stamp(?:ing)? authorit(?:y|ies)\b|\bTSA\b|\btransparency logs?\b|'
                                r'\bOpenTimestamps\b|\bpublic anchors?\b|\banchors? into a public chain\b|\bfinal witness(?:es)?\b|'
                                r'\btime.?stamp tokens?\b', re.I),
}
ROLE_DIRECTION = {
    'not-later-than': re.compile(r'\bnot[- ]later[- ]than\b|\bno later than\b|\bnot (?:been )?(?:made|taken|created|written|stamped|issued) '
                                 r'(?:any )?later\b|\bat the latest\b|\bexisted by\b|\bby then\b|\bbefore (?:that|then|it says)\b', re.I),
    'not-earlier-than': re.compile(r'\bnot[- ]earlier[- ]than\b|\bno earlier than\b|\bnot (?:been )?(?:made|taken|created|written|stamped|issued) '
                                   r'(?:any )?earlier\b|\bat the earliest\b|\bafter (?:that|then|it says)\b|'
                                   r'\bcould not have (?:been )?(?:known|existed|made) before\b', re.I),
}
ROLE_PROVES = {'freshness beacon': 'not-earlier-than', 'final witness': 'not-later-than'}
# A verifiable delay function proves sequential work and never elapsed time (rule 4).
DELAY_FUNCTION = re.compile(r'\b(?:verifiable )?delay functions?\b|\bVDFs?\b', re.I)
ELAPSED = re.compile(r'\belapsed\b|\bseconds?\b|\bminutes?\b|\bhours?\b|\bhow long\b|\bduration\b|\bwall.?clock\b|\breal time\b|'
                     r'\btime (?:passed|elapsed|has passed|went by)\b|\bpassage of time\b|\bmeasures? time\b|\bproves? time\b', re.I)
# The three millisecond figures rule 1 of what this product may say names as somebody else's, each with the conditions it
# belongs to, and the two the simulated harness produced. None of the five has been measured by
