def content_reader_reads_the_leaf():
    """Whether site_strings prunes a note's own string and nothing above or beside it. Until
    2026-09-16 a key that looked like a note pruned the object under it, and the front page's
    install note went unread."""
    seed = 'The install block says our clock is accurate to the microsecond.'
    faults = []
    for key in ('commandNote', 'gapNote', 'editorNote', 'srcNote', 'provenance', 'src', 'id', '$source'):
        if list(site_strings({key: seed})):
            faults.append(f'a string under the key {key} was read, and it is a note')
        if [s for _, s in site_strings({key: {'text': seed}})] != [seed]:
            faults.append(f'the object under the key {key} was pruned whole, and only its own string is a note')
    for key in NOT_SERVED_OBJECTS:
        if list(site_strings({key: [{'note': seed}, seed]})):
            faults.append(f'a string under {key} was read, and that object is editorial in full')
    if [s for _, s in site_strings({'install': {'commandNote': {'text': seed, 'src': 'x', 'id': 'y'}}})] != [seed]:
        faults.append('install.commandNote.text is not read, and the front page prints it')
    return faults


def every_attribute_a_reader_is_given_is_read(policy):
    """Whether a page is read through the contract, on each string a reader is given without seeing it.

    Until 2026-09-16 the lists were written out here and again in the site repository's picture
    reader, and they differed by `aria-description`: a rule-breaking sentence in that one attribute
    was refused inside a picture and passed on the page around it. So each attribute the contract
    names is watched carrying a sentence this file refuses, one at a time and nowhere else on the
    page, and the page is watched being refused for it.
    """
    faults = []
    seed = 'Our clock is accurate to the microsecond.'
    # Written out rather than read off the contract, because a test that iterates the list it is
    # checking goes quiet when the list shrinks. These four are the ones a screen reader speaks and
    # `aria-description` is the one a real fault used, so dropping any of them from the contract has
    # to fail here rather than silently stop being tested.
    for attribute in ('alt', 'title', 'aria-label', 'aria-description', 'aria-roledescription'):
        if attribute not in CONTRACT['attributes']:
            faults.append(f'the contract no longer names {attribute}, which a reader is given without '
                          f'seeing the page')
    for attribute in CONTRACT['attributes']:
        page = f'<html><body><p>The agent holds a bound.</p><img {attribute}="{seed}"></body></html>'
        if not [f for s in sentences(page_text(page)) for f in judge(s, policy)]:
            faults.append(f'a page carrying a refused sentence in {attribute} and nowhere else passed')
    for name in CONTRACT['metaNames']:
        page = f'<html><head><meta name="{name}" content="{seed}"></head><body><p>A bound.</p></body></html>'
        if not [f for s in sentences(page_text(page)) for f in judge(s, policy)]:
            faults.append(f'a page carrying a refused sentence in the {name} meta tag and nowhere else passed')
    if CONTRACT['pageTitle']:
        page = f'<html><head><title>{seed}</title></head><body><p>A bound.</p></body></html>'
        if not [f for s in sentences(page_text(page)) for f in judge(s, policy)]:
            faults.append('a page carrying a refused sentence in its title and nowhere else passed')
    # A block element still ends a sentence, so two list items are two sentences and the clause of
    # one does not reach into the other.
    run_on = page_text('<ul><li>signed evidence from outside parties</li><li>our own bound</li></ul>')
    if len(sentences(run_on)) < 2:
        faults.append('two list items were read as one sentence, so a block element is not ending one')
    return faults


def a_surface_hiding_the_ceiling_is_refused():
    """Whether a surface quoting the committed receipt's width without its ceiling is refused.

    Three probes, because the rule has three ways to be wrong and only the first is obvious. A
    surface that quotes the width and says nothing has to be named. A surface that states the
    ceiling anywhere in itself has to pass, since the rule is over a surface and not over a
    sentence, and that is the half that keeps the limitation list green. And a surface that states
    some other ceiling has to be refused, because the number is read off the receipt and a surface
    carrying the agent's 250 ms instead has not stated the condition this width was taken under.
    """
    faults = []
    width = 'a bound of 153.875 ms on the receipt committed in this repository'
    probes = [
        ('says nothing', [('a made-up surface', width)], True),
        ('states it elsewhere in itself',
         [('a made-up surface', width),
          ('a made-up surface', 'The ceiling it was signed under was 30 s until 2026-09-15.')], False),
        ('states another ceiling',
         [('a made-up surface', width),
          ('a made-up surface', 'The ceiling it was signed under was 250 ms.')], True),
    ]
    for what, read_from, refuse in probes:
        try:
            said = the_ceiling_is_stated(read_from)
        except (Unreadable, OSError) as e:
            return [f'the ceiling rule could not be run against a made-up surface: {e}']
        if refuse and not said:
            faults.append(f'a surface that quotes the committed receipt and {what} passed the ceiling rule')
        if not refuse and said:
            faults.append(f'a surface that quotes the committed receipt and {what} was refused: {said[0]}')
    return faults


def every_figure_is_read(policy):
    """Whether a figure nothing has a rule for is refused, watched on the three that were not.

    The three sentences below went through this file untouched at `c3a23c8`, which is what the walk
    over figures was written for, so they are watched being refused rather than assumed to be. The
    excuse list is watched too, on both halves of what makes it an excuse rather than a hole: an
    entry short of a reason stops the run outright, and one that covers a sentence the surfaces no
    longer carry is reported rather than left standing.
    """
    faults = []

    def refused_for(sentence, figure, surface='a made-up surface', excused=None):
        """The refusals of one sentence, and whether one of them names the figure the probe is for.

        A probe that asks only whether a sentence was refused passes on any figure in it, so a
        sentence carrying two is green while the one it was written for goes through. That held a
        walk green for a day on 2026-09-18, and this function carried the same shape on its first
        probe, whose sentence carries ninety-nine percent beside the 12 milliseconds it is for.
        """
        refused = unclaimed([(surface, sentence)], policy, None, [] if excused is None else excused)[0]
        return refused, any(f' {figure} ' in line.splitlines()[0] for line in refused)

    probes = [
        ('Ninety-nine percent of receipts come in under 12 milliseconds.', '12 milliseconds'),
        ('TimeWitness bounds every stamp at 153.875 ms.', '153.875 ms'),
        ('Every stamp carries an error bound of 128.7 ms.', '128.7 ms'),
        ('Measured on 2026-09-09 on an ordinary desktop, every stamp is 128.7 ms wide.', '128.7 ms'),
    ]
    for probe, figure in probes:
        refused, named = refused_for(probe, figure)
        if not named:
            faults.append(f'a figure nothing has a rule for passed, or the sentence was refused for another figure than {figure}: {probe}')
    # And the check above can tell the difference: with the figure a probe is for excused, the
    # sentence is still refused, for the other figure in it, and the probe no longer counts it.
    only = [{'figures': {'12 milliseconds'}, 'surfaces': {'a made-up surface'},
             'sentence': probes[0][0], 'reason': 'for the self-test', 'used': 0}]
    refused, named = refused_for(probes[0][0], '12 milliseconds', excused=only)
    if not refused or named:
        faults.append('with its figure excused, the first probe must be refused for the other figure and not counted, and was not')
    # An honest sentence of the same shape has to pass, or this is refusing figures rather than
    # unread ones.
    for honest in ('Measured 2026-09-09 at 21:41 on an ordinary desktop at sixteen rounds: 153.875 ms wide.',
                   'The agent refuses anything past its 250 ms ceiling.'):
        refused, _ = unclaimed([('a made-up surface', honest)], policy, None, [])
        if refused:
            faults.append(f'an honest figure was refused ({refused[0].splitlines()[0]}): {honest}')
    # A conditions word bolted onto a figure nobody measured. Each of these passed on
    # the word alone until 2026-09-16, bar the one starting "Ordinarily", and each is refused now
    # because 12 ms is in no register.
    for prefix in ('Measured on an ordinary desktop,', 'On an ordinary desktop,', 'Ordinarily,',
                   'On a GitHub runner,', 'Over sixteen polling rounds,', 'At thirty-six minutes of uptime,',
                   'Measured,', 'On a desktop,'):
        probe = f'{prefix} receipts come in under 12 ms.'
        if not refused_for(probe, '12 ms')[1]:
            faults.append(f'an invented figure passed on its conditions word, or was refused for another: {probe}')
    # Somebody else's figure written as ours, refused by what its entry says rather than by the word.
    public = 'Between 5 and 50 ms over the public internet, measured by us.'
    refused = unclaimed([('a made-up surface', public)], policy, None, [])[0]
    if not refused or 'public research' not in refused[0]:
        faults.append(f'a public research figure written as ours was not refused by name: {public}')
    # The width of a receipt since replaced, and a round count given a width nobody read.
    for stale, figure in (('Our bound was 149.8 ms on the receipt we ship as a fixture.', '149.8 ms'),
                          ('Sixteen polling rounds gets you under a hundred milliseconds of error.', 'hundred milliseconds')):
        if not refused_for(stale, figure)[1]:
            faults.append(f'a figure no register holds as said passed, or was refused for another than {figure}: {stale}')
    # The honest sentences of a cold set written from the product's rules alone and frozen at sha256
    # e4c2a62 before the figure walk was opened, all twelve, named, through both halves of this file.
    cold = {
        'C33': 'The receipt committed at `crates/verify/tests/data/a-real-stamp/receipt.cbor` gives 153.875 ms of half width, taken on an ordinary desktop on 2026-09-09 at 21:41 over sixteen polling rounds.',
        'C34': 'Measured on an ordinary desktop on 2026-09-09 at 22:17, at thirty-six minutes of uptime and a thirty-two second cadence, the agent read bounds of 128.7 ms, 128.8 ms and 129.1 ms.',
        'C35': "Of that 153.875 ms of width, 38.011 ms is the model's own regression residual doubled by the coverage factor and 35.081 ms is what the sources overlap on, read off `timewitness verify` on that receipt.",
        'C36': 'Public research puts a well disciplined clock at 5 to 50 ms over the public internet with no owned hardware, and none of that has been measured by us.',
        'C37': 'The shipped default is sixteen polling rounds.',
        'C38': 'The agent disciplines the clock against four to six independent sources.',
        'C39': 'The receipt names nine servers behind six operators and nine were kept.',
        'C40': 'The simulated network in `crates/clock/tests/common/mod.rs` gives 26.6 ms at synchronisation and 234.6 ms at fifteen minutes, which is the arithmetic of the model rather than a reading from a real path.',
        'C41': 'Nanoseconds is the resolution of the local read and milliseconds is the accuracy to UTC in the design.',
        'C42': 'A machine reaching three operators is under the shipped floor of four and is refused.',
        'C43': 'Install it with one line in a workflow file.',
        'C44': 'The adversarial plan holds twenty property attacks and five compound campaigns.',
    }
    for name, honest in cold.items():
        refused = judge(honest, policy) + unclaimed([('a made-up surface', honest)], policy, None, [])[0]
        if refused:
            faults.append(f'honest sentence {name} of the cold set was refused ({refused[0].splitlines()[0]}): {honest}')
    # A register entry that does not say where its figure came from stops the run.
    register_on_disk = parse_register(FIGURES_REGISTER.read_text(encoding='utf-8'))
    frame = {k: v for k, v in register_on_disk.items() if k != 'allowed'}
    fixture = 'crates/verify/tests/data/a-real-stamp/receipt.cbor'

    def ours(figure, **kw):
        """A complete measurement of ours held to the committed receipt, with fields overridden."""
        entry = {'figure': figure, 'unit': 'ms', 'precision': '0.001 ms', 'whose': 'ours', 'conditions': 'for the self-test',
                 'evidence': {'kind': 'receipt', 'artefact': fixture}, 'of': 'the whole interval',
                 'owner': {'machine': 'an ordinary desktop', 'path': 'the one-shot command'},
                 'setup': {'date': '2026-09-09', 'rounds': 16}}
        for key, value in kw.items():
            if value is None:
                entry.pop(key, None)
            else:
                entry[key] = value
        return entry

    def refused_naming(label, entry, needs='entry 1'):
        try:
            read_register(dict(frame, allowed=[entry]))
            faults.append(f'a register entry with {label} was read as an entry')
        except Unreadable as e:
            if needs not in str(e):
                faults.append(f'a register entry with {label} was refused without naming {needs}: {e}')

    for missing in ('figure', 'unit', 'whose', 'conditions', 'evidence', 'of', 'precision', 'owner', 'setup'):
        short = ours('153.875')
        del short[missing]
        refused_naming(f'no {missing}', short)
    # And the register is what answers: a sentence a rule cannot read passes once an entry holds its
    # figure, and the entry has to stand on evidence that carries it, here the committed receipt.
    invented = 'Measured, receipts come in under a bound of 153.875 ms.'
    held = read_register(dict(frame, allowed=[ours('153.875')]))
    if unclaimed([('a made-up surface', invented)], policy, None, [], held)[0]:
        faults.append('a figure the register holds was refused, so the register is not what answers')
    # What a registered figure is of, and whether the evidence for it resolves. Until 2026-09-17 the
    # register answered a figure by its number alone: an entry whose evidence was the word "none"
    # licensed an invented 12 ms, a margin was quoted as the whole bound, and the width of a receipt
    # since replaced was said in the present tense beside a sentence saying nothing had replaced it.
    forged = ours('12', precision='1 ms', evidence='none')
    try:
        read_register(dict(frame, allowed=[forged]))
        faults.append('a register entry of ours whose evidence is "none" was read as an entry')
    except Unreadable as e:
        if '12 ms' not in str(e) or 'the whole interval' not in str(e):
            faults.append(f'a register entry with no evidence was refused without naming the figure and what it is of: {e}')
    for requoted in ('The receipt committed today carries 149.8 ms, and nothing has replaced it.',
                     "Measured today, a stamp's error bound is 35.081 ms.",
                     "The model's own residual on the committed receipt is 153.875 ms."):
        refused = unclaimed([('a made-up surface', requoted)], policy, None, [])[0]
        if not refused:
            faults.append(f'a registered figure said as something it is not of passed: {requoted}')
        elif 'entry' not in refused[0]:
            faults.append(f'a registered figure said as something it is not of was refused without naming the entry: {refused[0].splitlines()[0]}')
    # What the afternoon of 2026-09-17 added, each watched refused and each naming the entry. The
    # owner of a figure, on both axes; a constant called measured, in each of its three shapes; a
    # history figure in the present; a superseded figure called today's in the sentence after it;
    # somebody else's figure said as measured by us; a setting called a bound.
    for wrong, needs in (
        ("The agent's bound on an ordinary desktop at sixteen polling rounds, measured on 2026-09-14, is 287.147 ms.", 'owner'),
        ('On an ordinary desktop the Action gave 211.3 ms on 2026-09-09 at sixteen polling rounds.', 'owner'),
        ('The one-shot stamp command reached 128.7 ms on an ordinary desktop at thirty-six minutes of uptime.', 'owner'),
        ('Through the resident agent, a GitHub-hosted runner on 2026-09-09 at sixteen polling rounds reached 211.3 ms.', 'owner'),
        ('The width breakdown safety margin of 250.000 us was measured on an ordinary desktop at sixteen polling rounds.', 'constant'),
        ('Measured on an ordinary desktop at sixteen polling rounds, the local read came to 10.000 us.', 'constant'),
        ('Measured on an ordinary desktop at sixteen polling rounds, the safety margin was 250.000 us.', 'constant'),
        ('A GitHub-hosted runner at four polling rounds reaches 16.219 s with Roughtime alone.', 'history'),
        ('On an ordinary desktop at four polling rounds the stamp is 16.439 s wide today.', 'history'),
        ('Our agent measured 15 microseconds of dispersion on an ordinary desktop.', 'we measured'),
        ('Measured on an ordinary desktop at sixteen polling rounds, the bound was 90 s.', 'calls it'),
    ):
        refused = unclaimed([('a made-up surface', wrong)], policy, None, [])[0]
        if not refused:
            faults.append(f'a registered figure said wrongly passed: {wrong}')
        elif needs not in refused[0] or 'entry' not in refused[0]:
            faults.append(f'a registered figure said wrongly was refused for the wrong reason or without the entry named ({refused[0].splitlines()[0]}): {wrong}')
    across = [('a made-up surface', 'The receipt of 149.8 ms was taken at 20:32 on an ordinary desktop at sixteen polling rounds and was replaced at 21:50.'),
              ('a made-up surface', 'That receipt is the one in the tree today.')]
    refused = unclaimed(across, policy, None, [])[0]
    if not refused or 'since replaced' not in refused[0]:
        faults.append('a superseded figure called today\'s in the sentence after it passed')
    # The owner read across the sentence where nothing names one beside the figure: after a list of
    # readings, in a relative clause, as the agent of a passive, in brackets, in a line of a table, and
    # the path axis the same way. Each was a miss on the afternoon's cold set.
    for wrong in (
        '128.7 ms, 128.8 ms and 129.1 ms came from a GitHub-hosted runner at sixteen polling rounds on 2026-09-09.',
        'The 211.3 ms, which the resident agent on an ordinary desktop reached at sixteen polling rounds on 2026-09-09, is the width to quote.',
        '287.147 ms was reached at sixteen polling rounds on 2026-09-14 by an ordinary desktop running the Action at v0.',
        'The agent (on a GitHub-hosted runner, sixteen polling rounds, 2026-09-09) read 128.8 ms.',
        '| GitHub-hosted runner | sixteen polling rounds | 2026-09-09 | committed receipt | 153.875 ms |',
        'The receipt is 153.875 ms wide; sixteen polling rounds; 2026-09-09; GitHub-hosted runner.',
        'The Action on a GitHub-hosted runner at sixteen polling rounds on 2026-09-09 read 128.8 ms.',
    ):
        refused = unclaimed([('a made-up surface', wrong)], policy, None, [])[0]
        if not refused or 'owner' not in refused[0] or 'entry' not in refused[0]:
            faults.append(f'a figure given to another owner elsewhere in its sentence passed or was refused for something else: {wrong}')
    for right in ('At sixteen polling rounds on 2026-09-09 the committed receipt is 153.875 ms wide.',
                  'Where a GitHub-hosted runner gave a bound of 287.147 ms on 2026-09-14 at sixteen polling rounds, the ordinary desktop\'s committed receipt of 2026-09-09 at sixteen polling rounds is 153.875 ms wide.',
                  'A GitHub-hosted runner on 2026-09-14, the Action at v0 at sixteen polling rounds, gave a bound of 287.147 ms.',
                  'Through the resident agent on an ordinary desktop on 2026-09-09 at thirty-six minutes of uptime, the bounds were 128.7 ms, 128.8 ms and 129.1 ms.',
                  'The safety margin in the width breakdown of the committed receipt is a fixed 250.000 us, a constant rather than a measurement.',
                  'Before the operator floor, on 2026-09-08, a GitHub runner at four polling rounds reached a bound of 16.219 s with Roughtime alone.'):
        refused = unclaimed([('a made-up surface', right)], policy, None, [])[0]
        if refused:
            faults.append(f'an honest sentence about a registered figure was refused ({refused[0].splitlines()[0]}): {right}')
    # The register itself: every field from its closed list, and evidence that resolves to something
    # other than a surface and carries the figure at the entry's precision, with the owner the
    # artefact's own record states. Each is refused naming the entry.
    receipt = lambda path: {'kind': 'receipt', 'artefact': path}
    runner = 'crates/verify/tests/data/a-runner-receipt-2026-09-09/receipt.hex'
    for label, bad in (
        ('evidence none under another whose', ours('12.4', precision='0.1 ms', whose='our own measurement', evidence='none')),
        ('whose written "ours, measured"', ours('153.875', whose='ours, measured')),
        ('whose not in the list', ours('153.875', whose='theirs')),
        ('a surface as the evidence', ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': 'README.md'})),
        ('the limitation list as the evidence', ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': 'docs/what-timewitness-cannot-prove.md'})),
        ('this register as the evidence', ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': 'scripts/figures.json'})),
        ('a served page as the evidence', ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': 'https://timewitness.dev/'})),
        ('a surface prose string as the evidence, not frozen', ours('12.4', precision='0.1 ms', evidence='docs/what-timewitness-cannot-prove.md, the section on what is built today')),
        ('a run id', ours('12.4', precision='0.1 ms', evidence='run 34349361290 of another repository')),
        ('evidence as a list', ours('12.4', precision='0.1 ms', evidence=['README.md'])),
        ('evidence as a number', ours('12.4', precision='0.1 ms', evidence=12.4)),
        ('a kind the list does not have', ours('153.875', evidence={'kind': 'blog', 'artefact': fixture})),
        ('an artefact that is a folder', ours('12.4', precision='0.1 ms', evidence=receipt('crates/clock/src/'))),
        ('a path escaping the repository', ours('12.4', precision='0.1 ms', evidence=receipt('../k09-note.md'))),
        ('a receipt whose field is another number', ours('72.433')),
        ('a receipt of another figure', ours('211.3', precision='0.1 ms')),
        ('a figure rounded wrongly at its stated place', ours('153.88', precision='0.01 ms')),
        ('a figure at a place it is not written to', ours('153.875', precision='0.01 ms')),
        ('a precision not in the list', ours('153.875', precision='a tenth ms')),
        ('a precision in another unit', ours('153.875', precision='0.001 s')),
        ('a precision that is not text', ours('153.875', precision=0.001)),
        ('a constant in the code for a measurement', ours('250', precision='1 ms', evidence={'kind': 'code', 'artefact': 'crates/clock/src/policy.rs'})),
        ('a figure written finer than its precision, held to code', ours('250.0', precision='1 ms', whose='ours, a setting', of='a ceiling', owner=None, setup=None, evidence={'kind': 'code', 'artefact': 'crates/clock/src/policy.rs'})),
        ('a surface as code evidence for a setting', ours('2', unit='s', precision='1 s', whose='ours, a setting', of='a ceiling', owner=None, setup=None, evidence={'kind': 'code', 'artefact': 'action.yml'})),
        ('an owner the register does not list', ours('153.875', owner={'machine': 'a phone', 'path': 'the one-shot command'})),
        ('an owner short of an axis', ours('153.875', owner={'machine': 'an ordinary desktop'})),
        ('an owner the provenance record contradicts', ours('153.875', owner={'machine': 'a GitHub-hosted runner', 'path': 'the one-shot command'})),
        ('a setup date the provenance record contradicts', ours('153.875', setup={'date': '2026-09-10', 'rounds': 16})),
        ('a setup date not written as a date', ours('153.875', setup={'date': 'yesterday', 'rounds': 16})),
        ('setup rounds in words', ours('153.875', setup={'date': '2026-09-09', 'rounds': 'sixteen'})),
        ('a setup with neither rounds nor cadence', ours('153.875', setup={'date': '2026-09-09'})),
        ('an owner on a figure that is not a measurement', ours('1', precision='1 ms', whose='public research, quoted', evidence={'kind': 'document', 'artefact': 'A paper'}, setup=None)),
        ('a document for a figure of ours', ours('153.875', evidence={'kind': 'document', 'artefact': 'A paper'})),
        ('a document named by a path', ours('1', precision='1 ms', whose='public research, quoted', owner=None, setup=None, evidence={'kind': 'document', 'artefact': 'docs/k17-note.md'})),
        ('a receipt the verifier refuses on its floor with no record naming that', ours('211.3', precision='0.1 ms', owner={'machine': 'a GitHub-hosted runner', 'path': 'the one-shot command'}, setup={'date': '2026-09-09', 'rounds': 16}, evidence=receipt(runner), of='the sources overlapping')),
    ):
        refused_naming(label, bad)
    for label, good in (
        ('a receipt carrying its figure', ours('153.875')),
        ('a figure at a coarser place, rounded right', ours('153.9', precision='0.1 ms')),
        ('a figure at a hundredth, rounded right', ours('153.87', precision='0.01 ms')),
        ('a receipt the verifier refuses on the operator floor, which its record names', ours('211.3', precision='0.1 ms', owner={'machine': 'a GitHub-hosted runner', 'path': 'the one-shot command'}, setup={'date': '2026-09-09', 'rounds': 16}, evidence=receipt(runner))),
        ('a setting held to the code', ours('250', precision='1 ms', whose='ours, a setting', of='a ceiling', owner=None, setup=None, evidence={'kind': 'code', 'artefact': 'crates/clock/src/policy.rs'})),
        ('a quoted figure held to a document', ours('1', precision='1 ms', whose='public research, quoted', owner=None, setup=None, evidence={'kind': 'document', 'artefact': 'A survey of clock synchronisation over the public internet'})),
    ):
        try:
            read_register(dict(frame, allowed=[good]))
        except Unreadable as e:
            faults.append(f'an entry with {label} was refused: {e}')
    # A receipt with no provenance record beside it, and a copy of the committed receipt with its
    # bound bytes moved, which the verifier refuses on its signature: each in a folder under the
    # build directory for the length of the check.
    import shutil as _shutil
    scratch = ROOT / 'target' / f'self-test-{os.getpid()}'
    try:
        bare = scratch / 'bare'
        bare.mkdir(parents=True, exist_ok=True)
        _shutil.copy(ROOT / fixture, bare / 'receipt.cbor')
        refused_naming('a receipt with no provenance record beside it',
                       ours('153.875', evidence=receipt((bare / 'receipt.cbor').relative_to(ROOT).as_posix())))
        forged_dir = scratch / 'forged'
        forged_dir.mkdir(parents=True, exist_ok=True)
        raw = bytearray((ROOT / fixture).read_bytes())
        raw[len(raw) // 2] ^= 0x01
        (forged_dir / 'receipt.cbor').write_bytes(bytes(raw))
        _shutil.copy(ROOT / 'crates/verify/tests/data/a-real-stamp' / PROVENANCE, forged_dir / PROVENANCE)
        refused_naming('a copy of the receipt with a byte changed, which the verifier refuses',
                       ours('153.875', evidence=receipt((forged_dir / 'receipt.cbor').relative_to(ROOT).as_posix())))
        # A record file, in the shape the register asks for, carrying a figure with its owner.
        record_dir = ROOT / RECORDS / f'self-test-{os.getpid()}'
        record_dir.mkdir(parents=True, exist_ok=True)
        record = record_dir / 'a-reading.json'
        record.write_text(json.dumps({'figures': ['12.4'], 'unit': 'ms', 'of': 'the whole interval', 'machine': 'an ordinary desktop',
                                      'path': 'the resident agent', 'date': '2026-09-17', 'rounds': 16}), encoding='utf-8')
        rel_record = record.relative_to(ROOT).as_posix()
        try:
            read_register(dict(frame, allowed=[ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': rel_record},
                                                  owner={'machine': 'an ordinary desktop', 'path': 'the resident agent'},
                                                  setup={'date': '2026-09-17', 'cadenceSeconds': 32})]))
        except Unreadable as e:
            faults.append(f'an entry held to a record in the shape the register asks for was refused: {e}')
        refused_naming('a record whose owner is not the entry\'s',
                       ours('12.4', precision='0.1 ms', evidence={'kind': 'record', 'artefact': rel_record},
                            setup={'date': '2026-09-17', 'rounds': 16}))
        refused_naming('a record stating another figure',
                       ours('12.5', precision='0.1 ms', evidence={'kind': 'record', 'artefact': rel_record},
                            owner={'machine': 'an ordinary desktop', 'path': 'the resident agent'},
                            setup={'date': '2026-09-17', 'cadenceSeconds': 32}))
    finally:
        _shutil.rmtree(scratch, ignore_errors=True)
        _shutil.rmtree(ROOT / RECORDS / f'self-test-{os.getpid()}', ignore_errors=True)
    # The frozen list: an entry on it is read with its surface prose, one changed in any field the
    # fingerprint covers is off it, and nothing joins it.
    frozen_entry = next(e for e in register_on_disk['allowed'] if fingerprint(e) in frame['$frozen']['fingerprints'])
    frozen_entry = json.loads(json.dumps(frozen_entry))
    try:
        read_register(dict(frame, allowed=[frozen_entry]))
    except Unreadable as e:
        faults.append(f'an entry on the frozen list was refused: {e}')
    moved = json.loads(json.dumps(frozen_entry))
    moved['conditions'] = moved['conditions'] + ' (changed)'
    refused_naming('a frozen entry changed in a field the fingerprint covers', moved)
    if not frame['$frozen']['fingerprints'] or len(frame['$frozen']['fingerprints']) != 33:
        faults.append(f'the frozen list holds {len(frame["$frozen"]["fingerprints"])} entries and 33 were frozen on 2026-09-17')
    # A key written twice is refused before any entry is read.
    try:
        parse_register('{"a": 1, "a": 2}')
        faults.append('a register object with a key written twice was parsed')
    except Unreadable:
        pass
    for said_right in ('In the width breakdown of the same receipt, the sources overlapping, halved, come to 35.081 ms, read off timewitness verify.',
                       'The receipt committed on 2026-09-09 at 20:32 was 149.8 ms wide and was replaced at 21:50 that day.'):
        refused = unclaimed([('a made-up surface', said_right)], policy, None, [])[0]
        if refused:
            faults.append(f'a registered figure said as what it is of was refused ({refused[0].splitlines()[0]}): {said_right}')
    # A spelled hundred is read whole, so two hundred milliseconds is not a hundred.
    if [t for t, _, _ in figures_of('a liar two hundred milliseconds out')] != ['two hundred milliseconds']:
        faults.append('two hundred milliseconds was not read as one figure')
    # The excuse itself, watched covering the sentence it names and nothing beside it.
    entry = [{'figures': {'12 milliseconds', 'ninety-nine percent'}, 'surfaces': {'a made-up surface'},
              'sentence': probes[0][0], 'reason': 'for the self-test', 'used': 0}]
    if unclaimed([('a made-up surface', probes[0][0])], policy, None, entry)[0]:
        faults.append('an excused figure was refused in the sentence its entry quotes')
    if not all(refused_for(probes[0][0], figure, 'another surface', entry)[1]
               for figure in ('12 milliseconds', 'ninety-nine percent')):
        faults.append('an excuse covered a surface it does not name, for one of its two figures')
    entry[0]['used'] = 0
    if not all(refused_for('Ninety-nine percent of receipts come in under 12 milliseconds today.', figure,
                           excused=entry)[1] for figure in ('12 milliseconds', 'ninety-nine percent')):
        faults.append('an excuse covered a sentence it does not quote, for one of its two figures')
    if not stale_excuses(entry, {'a made-up surface'}):
        faults.append('an entry that matched nothing on a surface it names was not reported')
    if stale_excuses(entry, {'another surface'}):
        faults.append('an entry was called stale on a run that did not read the surface it names')
    # An excuse with no reason beside it is the same failure as a skipped check, so it stops the run
    # rather than being skipped over.
    whole = {'reasons': {'for the self-test': 'A reason written out at the length this file asks for.'},
             'excused': [{'figures': ['1 ms'], 'surfaces': ['x'], 'sentence': 'One.',
                          'reason': 'for the self-test'}]}
    for missing in ('figures', 'surfaces', 'sentence', 'reason'):
        short = json.loads(json.dumps(whole))
        del short['excused'][0][missing]
        try:
            read_excuses(short)
            faults.append(f'an entry with no {missing} was read as an excuse')
        except Unreadable:
            pass
    unwritten = json.loads(json.dumps(whole))
    unwritten['excused'][0]['reason'] = 'a reason nobody wrote out'
    try:
        read_excuses(unwritten)
        faults.append('an entry naming a reason the file does not write out was read as an excuse')
    except Unreadable:
        pass
    thin = json.loads(json.dumps(whole))
    thin['reasons']['for the self-test'] = 'Because.'
    try:
        read_excuses(thin)
        faults.append('a reason of one word was read as a reason')
    except Unreadable:
        pass
    return faults


ATTRIBUTIONS_RECORD = ROOT / 'scripts' / 'policy-attributions.txt'
# The closed list of ways a sentence gives a figure to a subject, each the part of the sentence
# from the verb on, and the adjectives the vocabulary does not list that may sit in front of the
# subject word. The generated grade below is the cross product of these with every phrase of every
# other subject in every form the fold admits, for every entry.
UNLISTED_ADJECTIVES = ('whole', 'full', 'entire')
ATTRIBUTIONS_VERSION = 1


def inflections(word, suffixes):
    """Every form of a word the fold reads as the word: the word, its stem with each suffix, and
    where the stem ends in one consonant after a vowel, that consonant doubled before -ed and
    -ing."""
    root = stem(word, suffixes)
    out = [word]
    for suffix in suffixes:
        out.append(root + suffix)
    last = root[-1]
    if last not in 'aeiou' and last.isalpha() and len(root) >= 3 and root[-2] in 'aeiou' and root[-3] not in 'aeiou':
        out.append(root + last + 'ed')
        out.append(root + last + 'ing')
    return out


def attributing_phrasings(figure, unit, phrase, subject_is_whole):
    f = f'{figure} {unit}'
    yield 'directly after the figure', f'was {f} {phrase}'
    yield 'after of', f'was {f} of {phrase}'
    yield 'after of the', f'was {f} of the {phrase}'
    yield 'after of its', f'was {f} of its {phrase}'
    yield 'after of that', f'was {f} of that {phrase}'
    for adjective in UNLISTED_ADJECTIVES:
        yield f'after of and the unlisted adjective {adjective}', f'was {f} of {adjective} {phrase}'
        yield f'after of the and the unlisted adjective {adjective}', f'was {f} of the {adjective} {phrase}'
    yield 'the subject fronted before the figure', f'{phrase} was {f}'
    if not subject_is_whole:
        yield 'the figure written wide', f'was {f} wide'


def attribution_conditions(entry):
    """A conditions clause the entry's own rules accept: its machine, its date, its rounds or
    cadence, the phrase it has to be said with, a path where it is a setting."""
    setup = entry.get('setup') or {}
    owner = entry.get('owner') or {}
    said = list(entry.get('saidWith') or [])
    nearby = entry.get('requiresNearby')
    parts = []
    if owner:
        parts.append(f'on {owner["machine"]}')
        if 'rounds' in setup:
            rounds = setup['rounds']
            parts.append(f'at {rounds[0] if isinstance(rounds, list) else rounds} polling rounds')
        elif 'cadenceSeconds' in setup:
            parts.append(f'at a {setup["cadenceSeconds"]} second cadence')
        if setup.get('date'):
            parts.append(f'on {setup["date"]}')
    elif nearby:
        parts.append(nearby)
    elif said:
        parts.append(f'on the {said[0]} network on 2026-09-07')
    else:
        evidence = entry.get('evidence')
        artefact = evidence.get('artefact') if isinstance(evidence, dict) else None
        if artefact and '/' in artefact:
            parts.append(f'in {artefact}')
        elif entry['whose'] == 'the NTP wire format':
            parts.append('quoted from the protocol document')
        else:
            parts.append('in docs/what-timewitness-cannot-prove.md')
    if entry.get('superseded') and said:
        parts.append(said[0])
    elif entry.get('history') and not setup.get('date'):
        parts.append('until 2026-09-15')
    return ', '.join(parts)


def attributions(data):
    """The generated grade: for every entry and every phrase naming every other subject, every
    attributing phrasing in every form the fold admits, each giving the entry's figure to the wrong
    subject and each to be refused naming the subject; and one base sentence per entry in its own
    subject, to pass, so a wrong one refused for some other reason shows as such. Yields
    (id, entry number, expected, wrong subject key, phrasing, form, sentence)."""
    named, _, suffixes = read_subjects(data)
    # Two entries can hold one figure, "2 s" being both a ceiling and the outside signatures' gap,
    # so a subject some other entry of the same figure has is not a wrong subject for it.
    subjects_of_figure = {}
    for entry in data['allowed']:
        for figure in (entry['figure'] if isinstance(entry['figure'], list) else [entry['figure']]):
            subjects_of_figure.setdefault((figure, entry['unit']), set()).add(entry['of'])
    n = 0
    for number, entry in enumerate(data['allowed'], 1):
        figure = entry['figure']
        figure = figure[0] if isinstance(figure, list) else figure
        unit = entry['unit']
        own = entry['of']
        honest_elsewhere = subjects_of_figure[(figure, unit)]
        own_phrases = named[own]['namedBy']
        lead = attribution_conditions(entry)
        lead = lead[0].upper() + lead[1:]
        n += 1
        if own_phrases:
            yield f'A{n:05d}', number, 'PASS', '-', 'the base sentence', '-', f'{lead}, the {own_phrases[0]} was {figure} {unit}.'
        else:
            yield f'A{n:05d}', number, 'PASS', '-', 'the base sentence', '-', f'{lead}, it was {figure} {unit}.'
        for key, subject in named.items():
            if key in honest_elsewhere:
                continue
            for phrase in subject['namedBy']:
                words = phrase.split()
                for form in inflections(words[-1], suffixes):
                    formed = ' '.join(words[:-1] + [form])
                    for phrasing, tail in attributing_phrasings(figure, unit, formed, own == 'the whole interval'):
                        if phrasing == 'the figure written wide' and form != words[-1]:
                            continue
                        n += 1
                        if phrasing == 'the subject fronted before the figure':
                            yield f'A{n:05d}', number, 'REFUSE', key, phrasing, formed, f'{lead}, the {tail}.'
                        else:
                            yield f'A{n:05d}', number, 'REFUSE', key, phrasing, formed, f'{lead}, it {tail}.'


def vocabulary_fingerprint(data):
    return hashlib.sha256(json.dumps(data['$subjects'], sort_keys=True).encode()).hexdigest()


def attributions_record(data):
    """What the record of the generated grade has to say for this register: the vocabulary's
    fingerprint, the generator's version and the number of lines."""
    lines = sum(1 for _ in attributions(data))
    return (f'# The generated grade of {FIGURES_REGISTER.name}: every entry given to every other subject in every '
            f'phrasing and form. Written by --attributions; --self-test refuses a register whose vocabulary has '
            f'changed since.\nvocabulary {vocabulary_fingerprint(data)}\ngenerator {ATTRIBUTIONS_VERSION}\nlines {lines}\n')


def the_register_holds_a_figure_to_its_subject(policy):
    """The fold has no collisions, the generated grade is refused line by line, and a sentence that
    names no subject, or two owners on an axis, is refused rather than passed."""
    faults = []
    data = parse_register(FIGURES_REGISTER.read_text(encoding='utf-8'))
    named, neutral, suffixes = read_subjects(data)
    owners = read_owners(data)
    # No two subjects share a folded phrase, no subject's phrase folds to a neutral one, and no two
    # owners on an axis share a folded word: over every phrase, because the list is small enough for
    # that to be exhaustive, and that assertion is what makes the fold a closed rule.
    seen = {}
    for key, subject in named.items():
        for phrase in subject['namedBy']:
            folded = stems(phrase, suffixes)
            if folded in seen and seen[folded] != key:
                faults.append(f'"{phrase}" of {key} and a phrase of {seen[folded]} fold to the same stems {folded}')
            seen[folded] = key
    for phrase in neutral:
        if stems(phrase, suffixes) in seen:
            faults.append(f'the neutral phrase "{phrase}" folds to the stems of a phrase of {seen[stems(phrase, suffixes)]}')
    for axis, names in owners.items():
        seen_words = {}
        for owner, words in names.items():
            for word in words:
                folded = stems(word, suffixes)
                if folded in seen_words and seen_words[folded] != owner:
                    faults.append(f'"{word}" of {owner} and a word of {seen_words[folded]} fold alike on the {axis} axis')
                seen_words[folded] = owner
    for word, stemmed in (('overlapped', 'overlap'), ('overlapping', 'overlap'), ('overlaps', 'overlap'),
                          ('overlappings', 'overlap'), ('widths', 'width'), ('bounds', 'bound'), ('ceilings', 'ceil'),
                          ('ceiling', 'ceil'), ('wide', 'wide'), ("agent's", 'agent')):
        if stem(word, suffixes) != stemmed:
            faults.append(f'"{word}" folds to "{stem(word, suffixes)}" rather than "{stemmed}"')
    # The record of the generated grade agrees with the register on disk, or the vocabulary grew
    # and nobody regenerated the set.
    wanted = attributions_record(data)
    if not ATTRIBUTIONS_RECORD.is_file() or ATTRIBUTIONS_RECORD.read_text(encoding='utf-8') != wanted:
        faults.append(f'{ATTRIBUTIONS_RECORD.name} does not match the register: the vocabulary or the generator '
                      f'changed and the generated grade was not regenerated; run --attributions')
    # Every line of the generated grade, through the register answer alone.
    known = read_register(data)
    passed = []
    base_refused = []
    for ident, number, expected, wrong, phrasing, form, sentence in attributions(data):
        entry = data['allowed'][number - 1]
        figure = entry['figure'][0] if isinstance(entry['figure'], list) else entry['figure']
        # The entry's own figure, not a condition written before it: "at a 32 second cadence" is a
        # figure too.
        wanted = f'{figure} {entry["unit"]}'.lower()
        # A range, "5 to 50 ms", is read at its upper figure.
        figures = [f for f in figures_of(sentence) if f[0] == wanted or wanted.endswith(' ' + f[0])]
        if not figures:
            faults.append(f'{ident} carries no figure this reads as the entry has it: {sentence}')
            continue
        text, start, end = figures[0]
        entry, why = in_register(text, sentence, known, start, end)
        if expected == 'PASS' and entry is None:
            base_refused.append(f'{ident} (entry {number}): {sentence} | {why}')
        elif expected == 'REFUSE' and (entry is not None or 'calls it' not in why):
            passed.append(f'{ident} (entry {number}, {phrasing}, "{form}"): {sentence} | {why}')
    for line in base_refused[:5]:
        faults.append(f'a base sentence of the generated grade, in its own subject, was refused: {line}')
    if len(base_refused) > 5:
        faults.append(f'and {len(base_refused) - 5} more base sentences were refused')
    for line in passed[:10]:
        faults.append(f'a sentence giving a figure to the wrong subject was not refused naming the subject: {line}')
    if len(passed) > 10:
        faults.append(f'and {len(passed) - 10} more sentences of the generated grade were not refused')
    # The two branches that used to give the permitting answer to what they could not read.
    unreadable = ('On an ordinary desktop at sixteen polling rounds on 2026-09-09, the one-shot command reached 38.011 ms.',
                  'On an ordinary desktop at thirty-six minutes of uptime on 2026-09-09, the readings were 128.7 ms, 128.8 ms and 129.1 ms.')
    for sentence in unreadable:
        text, start, end = next(f for f in figures_of(sentence) if f[0].endswith(' ms'))
        entry, why = in_register(text, sentence, known, start, end)
        if entry is not None or 'cannot be read' not in why:
            faults.append(f'a sentence naming no subject the reader can see was not refused as unreadable: {sentence} | {why}')
    marked = 'In the width breakdown of the committed receipt, on an ordinary desktop at sixteen polling rounds on 2026-09-09, the residual came to 38.011 ms.'
    text, start, end = figures_of(marked)[0]
    entry, why = in_register(text, marked, known, start, end)
    if entry is None:
        faults.append(f'a sentence naming its subject after a breakdown marker was refused: {why}')
    two = ('The ordinary desktop and the GitHub-hosted runner were both read on 2026-09-09 at sixteen polling rounds, '
           'and the committed receipt is 153.875 ms wide.')
    text, start, end = figures_of(two)[0]
    entry, why = in_register(text, two, known, start, end)
    if entry is not None or 'machine axis' not in why or 'an ordinary desktop' not in why or 'a GitHub-hosted runner' not in why:
        faults.append(f'a sentence naming two owners on an axis was not refused naming the axis and both: {two} | {why}')
    for inflected in ('On an ordinary desktop at sixteen polling rounds on 2026-09-09, the sources overlapped by 153.875 ms.',
                      'On an ordinary desktop at sixteen polling rounds on 2026-09-09, the one-shot command reached 38.011 ms of whole interval.'):
        text, start, end = figures_of(inflected)[0]
        entry, why = in_register(text, inflected, known, start, end)
        if entry is not None or 'calls it' not in why:
            faults.append(f'a figure given to the wrong subject through an inflection or an unlisted adjective passed: {inflected} | {why}')
    own = 'On an ordinary desktop at sixteen polling rounds on 2026-09-09, the residuals came to 38.011 ms.'
    text, start, end = figures_of(own)[0]
    entry, why = in_register(text, own, known, start, end)
    if entry is None:
        faults.append(f'a figure given to its own subject through an inflection was refused: {why}')
    return faults


def the_fetch_refuses_a_redirect():
    """A local server answers 302 on every path, and the fetch has to refuse each one by name.

    It is here rather than in a file beside it because the fault was in the one function nothing
    tested: `served_text` is the only thing in this product that reads what a visitor is actually
    given, and it followed a redirect in silence. The server below is that measurement made
    repeatable, and the three cases after it are the ones a rewrite of this function would
    otherwise break quietly.
    """
    import http.server
    import threading

    faults = []

    class Answers(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path == '/elsewhere':
                body = b'<p>A real page, well over the sentence floor.</p>'
                self.send_response(200)
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)
            elif self.path == '/missing':
                self.send_error(404)
            else:
                self.send_response(302)
                self.send_header('Location', '/elsewhere')
                self.end_headers()

        def log_message(self, *_):
            pass

    server = http.server.HTTPServer(('127.0.0.1', 0), Answers)
    base = f'http://127.0.0.1:{server.server_address[1]}'
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        for page in SITE_PAGES:
            try:
                served_text(base + page)
                faults.append(f'{page} answered 302 to /elsewhere and was read as though it were {page}')
            except Unreadable as e:
                if '/elsewhere' not in str(e) or page not in str(e):
                    faults.append(f'the refusal of {page} names neither the path asked for nor the '
                                  f'one landed on: {e}')
        # What was already right and stays right: a page that answers is read, and a 404 is an error
        # rather than an empty page read as honest.
        if 'real page' not in served_text(base + '/elsewhere'):
            faults.append('a page that answers on the path asked for is no longer read')
        try:
            served_text(base + '/missing')
            faults.append('a 404 no longer fails the fetch')
        except urllib.error.HTTPError:
            pass
    finally:
        server.shutdown()
        server.server_close()

    # The one hop that is followed, and the shapes that look like it and are not.
    allowed = ('http://timewitness.dev/cannot-prove', 'https://timewitness.dev/cannot-prove')
    if not only_the_scheme(*allowed):
        faults.append('an upgrade to https on the same host and path is meant to be followed')
    for asked, to in [('http://timewitness.dev/', 'https://timewitness.dev/screen'),
                      ('http://timewitness.dev/', 'https://www.timewitness.dev/'),
                      ('https://timewitness.dev/', 'http://timewitness.dev/'),
                      ('http://timewitness.dev/', 'https://timewitness.dev/?preview=1')]:
        if only_the_scheme(asked, to):
            faults.append(f'{asked} to {to} is more than an upgrade of the scheme and was allowed')
    return faults


FITTED = ROOT / 'scripts' / 'policy-sentences-fitted.txt'
FITTED_SENTENCES = ROOT / 'scripts' / 'policy-sentences-fitted-sentences.txt'

# What a set is scored on, and when there is too little of it.
#
# Every line of a set that is recorded material, or a light rewrite of it, is named, with the
# recorded sentence it matches, and taken out of the count; the score is taken on the residue, the
# lines marked to be refused that nothing here has seen, and the size of that residue is printed
# beside the score. A set is refused where fewer than `SENTENCE_FLOOR` such lines are left, which
# is the floor this file already applies to a surface, because a number taken on four sentences is
# not a number. Until 2026-09-18 there was a threshold beside this, one in ten of a set's lines
# recorded here and the whole set refused. It was answering two questions and neither well: whether a
# set was written by reading this file's material is answered by the sha256 frozen before this file
# is opened and by the author saying they had not; how much of a set this file has already seen is
# what the matching measures, and it is reported now rather than thresholded. Recorded material grows
# with every set that measures this file and the matching improves with every fix to it, so a fixed
# share is crossed by more sets each week, and the five sentences that first crossed it were the
# obvious false claims about bounded time, which any competent set writes on its own. A fitted line
# never counts whichever side of the floor a set falls, so padding a fitted set with new sentences
# buys nothing: what is left to score is only the new sentences. The residue is counted over the
# lines the set marks to be refused, and over a line whose marker this cannot read, because those are
# what the number a set produces is taken on. It is never counted over `~` lines, which the set
# excludes by name, and never over the honest `+` lines: two writers quoting one specification land
# on the same honest sentence, and a cold set whose honest half is the specification's own wording is
# still cold on the half that is scored. Every match on either side is named and out of the count.

# What a light rewrite of a recorded sentence is, said once and closed.
#
# The material this file was shaped around is every sentence of a fitted set, every seed and every
# honest sentence below, and a line that is one of them, or a light rewrite of one, is read as fitted
# whichever list it came from. A light rewrite is any combination of four things and nothing else.
# Every change `sentence_tokens` folds: case, marks, format and invisible characters, look-alike
# letters, whitespace, punctuation, numbering and markup. Word edits, at most this many for a sentence
# of ten words or more, one in five to nine words and none under five, where an edit is a word
# substituted, inserted or deleted, a negation included, or two words of the sentence swapped,
# whether or not they are neighbours; the words are read as a bag, so clauses in another order cost
# nothing. The result held whole inside a longer line, or a
# line of at least `FEWEST_LETTERS` letters held whole inside it. Lines or clauses reordered, up to
# three sentences merged on one line, or a sentence split into parts that are each at least
# `FEWEST_LETTERS` letters or sit on adjacent lines in order.
#
# Until the evening of 2026-09-17 the reading past the print was a ratio, nine tenths of the letters
# alike as sequences, and that had two faults the closed list does not: a sentence three or four edits
# from a recorded one could be named as a match, which is a false match against an honest cold set,
# and a seed or an honest sentence one word off, which is recorded material, was not seen at all. A
# rewrite past the list, the passive, a translation, more edits than this, or fragments under
# `FEWEST_LETTERS` letters scattered out of order, shares too little with its source to be told from
# an honest sentence and is not seen; nothing made of words can see it.
EDITS_IN_A_LONG_SENTENCE = 2
EDITS_IN_A_SHORT_SENTENCE = 1
# The members of that list, one name each. The self-test holds a walk to every one of them and goes
# red where a member has none, because on 2026-09-17 the walk for two words swapped used neighbours
# only, which is the one arm the code had, so the walk and the code agreed about a case neither
# covered. A walk written by the hand that wrote the guard tests the understanding and not the code;
# a list the walks are held to at least says what the understanding has to cover.
LIGHT_REWRITES = (
    'case', 'marks and invisible characters', 'look-alike letters', 'whitespace', 'punctuation',
    'numbering', 'markup', 'a digit drawn for a letter', 'a letter doubled',
    'a word substituted', 'a word inserted', 'a word deleted', 'a negation included',
    'two neighbouring words swapped', 'two words swapped across a gap of two',
    'two words swapped across a gap of three', 'two words swapped across a gap of five',
    'a swap across a gap with a word substituted', 'a swap across a gap with a word deleted',
    'a swap across a gap with a word inserted', 'two swaps across gaps',
    'a swap across a gap in a sentence of five to nine words',
    'held whole inside a longer line', 'a part of at least the fewest letters', 'lines reordered',
    'clauses reordered', 'three sentences merged on one line', 'split into parts on adjacent lines',
    'the seeds, one word changed', 'the honest sentences, marked to be refused',
)
LONG_SENTENCE = 10
SHORT_SENTENCE = 5
# A run of letters shorter than this is not compared whole, because a short honest clause quoted from
# the specification sits inside longer sentences that quote it too.
FEWEST_LETTERS = 20

# Written out rather than escaped inline, so a line of a set built here cannot be mangled by the
# quoting of whatever wrote it.
NEWLINE = chr(10)

# Letters from other scripts drawn the same as a Latin letter, read as that letter. Until 2026-09-17
# one Cyrillic a per line walked a fitted set round the print.
LOOKALIKES = str.maketrans({
    '\u0430': 'a', '\u0435': 'e', '\u043e': 'o', '\u0440': 'p', '\u0441': 'c', '\u0445': 'x', '\u0443': 'y',
    '\u0456': 'i', '\u0458': 'j', '\u0455': 's', '\u04bb': 'h', '\u0501': 'd', '\u051b': 'q', '\u051d': 'w',
    '\u0410': 'a', '\u0412': 'b', '\u0415': 'e', '\u041a': 'k', '\u041c': 'm', '\u041d': 'h', '\u041e': 'o',
    '\u0420': 'p', '\u0421': 'c', '\u0422': 't', '\u0425': 'x', '\u0423': 'y',
    '\u03b1': 'a', '\u03b5': 'e', '\u03b9': 'i', '\u03ba': 'k', '\u03bd': 'v', '\u03bf': 'o', '\u03c1': 'p',
    '\u03c4': 't', '\u03c5': 'u', '\u03c7': 'x', '\u0391': 'a', '\u0392': 'b', '\u0395': 'e', '\u0397': 'h',
    '\u0399': 'i', '\u039a': 'k', '\u039c': 'm', '\u039d': 'n', '\u039f': 'o', '\u03a1': 'p', '\u03a4': 't',
    '\u03a5': 'y', '\u03a7': 'x', '\u0192': 'f', '\u0261': 'g', '\u026a': 'i', '\u0274': 'n', '\u0280': 'r',
    '\u1d00': 'a', '\u1d04': 'c', '\u1d05': 'd', '\u1d07': 'e', '\u1d0a': 'j', '\u1d0b': 'k', '\u1d0d': 'm',
    '\u1d0f': 'o', '\u1d18': 'p', '\u1d1b': 't', '\u1d1c': 'u', '\u1d20': 'v', '\u1d21': 'w', '\u1d22': 'z',
})


def sentence_tokens(line):
    """The words of a sentence as read, or None where the line is a comment or holds no words.

    Compatibility normalisation, then every combining mark and every format character taken out, so a
    zero-width space, a soft hyphen and an accent added to a letter leave the word it was in; then
    case folded and look-alike letters folded; then every run of letters and digits is one word, in
    order. Whatever a set's file does to a sentence without changing its words gives the same tokens:
    the marker in front of it, spacing, a line ending, a curly quote, a full stop dropped, a capital
    lowered, a Cyrillic a, an invisible character inside a word.
    """
    text = unicodedata.normalize('NFKD', line)
    text = ''.join(ch for ch in text if unicodedata.category(ch) not in ('Mn', 'Mc', 'Me', 'Cf'))
    text = unicodedata.normalize('NFKC', text).strip()
    if not text or text.startswith('#'):
        return None
    text = text.casefold().translate(LOOKALIKES)
    tokens = re.findall(r'[^\W_]+', text)
    return tokens or None


def print_of(tokens):
    return hashlib.sha256(' '.join(tokens).encode('utf-8')).hexdigest()


def sentence_print(line):
    """The sha256 of a sentence as its words, or None where the line is a comment or holds no words."""
    tokens = sentence_tokens(line)
    return print_of(tokens) if tokens else None


def sentence_prints_of(text):
    """The print and the words of every sentence line in a set, in order."""
    out = []
    for line in text.splitlines():
        tokens = sentence_tokens(line)
        if tokens:
            out.append((print_of(tokens), tokens))
    return out


def fitted_sets():
    """Every set that has measured this file, by sha256, read off the list beside it."""
    if not FITTED.is_file():
        raise Unreadable(f'{FITTED.name} is not beside this script, so nothing can say whether a set '
                         f'has already been folded in')
    known = {}
    for line in FITTED.read_text(encoding='utf-8').splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        parts = line.split(None, 3)
        if len(parts) != 4 or parts[1] not in ('fitted', 'scored'):
            raise Unreadable(f'{FITTED.name}: "{line[:70]}" is not a sha256, fitted or scored, a date '
                             f'and a name')
        known[parts[0].lower()] = {'state': parts[1], 'frozen': parts[2], 'name': parts[3]}
    return known


class Fitted:
    """One recorded sentence, ready to be compared with."""

    __slots__ = ('digest', 'names', 'tokens', 'letters', 'bag', 'edits')

    def __init__(self, digest, name, tokens):
        self.digest = digest
        self.names = {name}
        # A sentence recorded by its print alone has no words here, and is matched by its print alone.
        # The words are held as compared, see `comparable`; the print is the print of the words as
        # recorded, so a print recorded before this fold existed still matches.
        self.tokens = comparable(tokens) if tokens else tokens
        self.letters = ''.join(self.tokens) if tokens else ''
        self.bag = collections.Counter(self.tokens) if tokens else None
        self.edits = allowance(len(tokens)) if tokens else 0


# A digit drawn in place of a letter inside a word, read as that letter; a word of digits alone is a
# number and is left as it is.
DIGIT_LETTERS = str.maketrans({'0': 'o', '1': 'l', '3': 'e', '4': 'a', '5': 's', '7': 't', '8': 'b'})


def comparable(tokens):
    """The words as they are compared: a digit inside a word read as the letter it is drawn for, and
    a letter doubled read once. Both are the fold of `sentence_tokens` carried into the word itself,
    where a cold set wrote cl0ck and eveery and the print no longer saw the word."""
    out = []
    for token in tokens:
        if token.isdigit():
            out.append(token)
            continue
        if any(ch.isalpha() for ch in token):
            token = token.translate(DIGIT_LETTERS)
        out.append(re.sub(r'(.)\1+', r'\1', token))
    return out


def allowance(words):
    """How many word edits a light rewrite of a sentence of this many words may carry."""
    if words >= LONG_SENTENCE:
        return EDITS_IN_A_LONG_SENTENCE
    if words >= SHORT_SENTENCE:
        return EDITS_IN_A_SHORT_SENTENCE
    return 0


def edits_between(bag, other):
    """The fewest substitutions, insertions or deletions between two bags of words.

    A substitution takes one word out and puts one in, so it is one on each side; an insertion or a
    deletion is one on one side. The fewest edits is therefore the larger of the two sides, and two
    words swapped, or the clauses in another order, is nought.
    """
    return max(sum((bag - other).values()), sum((other - bag).values()))


def recorded_sentences(known):
    """Everything this file was shaped around: the fitted sets' sentences, the seeds and the honest ones."""
    recorded = fitted_sentences(known)
    for name, lines in (('the seeds of this file', [s for _, s in SEEDS]),
                        ('the honest sentences of this file', HONEST)):
        for line in lines:
            tokens = sentence_tokens(line)
            if tokens:
                recorded.append(Fitted(print_of(tokens), name, tokens))
    return recorded


def fitted_sentences(known):
    """The sentences of every fitted set, held to the list in both directions.

    They live in a file of their own on purpose. An entry deleted from the list leaves them where they
    are, and a fitted set with sentences and no entry, or an entry and no sentences, is refused by name
    rather than read past: either is a record that has been edited round, and a score taken beside it
    is not a score. Each line carries the print, the set and the words, because a print alone can say
    whether a sentence is the same and never whether it is a version of one. A line may carry the
    print and the set alone, where a sentence's words are not written here; that sentence is matched
    by its print and a version of it is not seen.
    """
    if not FITTED_SENTENCES.is_file():
        raise Unreadable(f'{FITTED_SENTENCES.name} is not beside this script, so a fitted set whose '
                         f'file has changed by a byte cannot be recognised')
    by_print = {}
    for number, line in enumerate(FITTED_SENTENCES.read_text(encoding='utf-8').splitlines(), 1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        parts = line.split(None, 2)
        if len(parts) < 2 or not re.fullmatch(r'[0-9a-f]{64}', parts[0]):
            raise Unreadable(f'{FITTED_SENTENCES.name} line {number}: "{line[:70]}" is not a sha256, '
                             f'the name of a fitted set and the words of the sentence; record a set '
                             f'with --prints')
        digest, name = parts[0], parts[1]
        words = parts[2].split() if len(parts) == 3 else None
        if digest in by_print:
            by_print[digest].names.add(name)
        else:
            by_print[digest] = Fitted(digest, name, words)
    named_there = {n for f in by_print.values() for n in f.names}
    named_fitted = {v['name'] for v in known.values() if v['state'] == 'fitted'}
    for name in sorted(named_there - named_fitted):
        raise Unreadable(f'{name} has sentences recorded as fitted in {FITTED_SENTENCES.name} and no '
                         f'fitted entry in {FITTED.name}, so its entry has gone and the set is still fitted')
    for name in sorted(named_fitted - named_there):
        raise Unreadable(f'{name} is fitted in {FITTED.name} and has no sentences in '
                         f'{FITTED_SENTENCES.name}, so a copy of it with one byte changed would score')
    return list(by_print.values())


def fitted_in_substance(line, fitted):
    """The recorded sentence this line is a light rewrite of, and how it was recognised, or None.

    Each reading is one item of the closed list above `EDITS_IN_A_LONG_SENTENCE`, and nothing outside
    that list is named: a line the list does not reach is not a match, whatever else it shares. The
    same words, by the print. The same letters once spaces are gone. The words within the edits the
    recorded sentence's length allows, counted along the sentence, with the line's clauses taken in
    any order. A window of the line within those edits of the recorded sentence, which is the
    sentence held whole inside a longer line, or three merged on one. A line of at least
    `FEWEST_LETTERS` letters that is a window of the recorded sentence within those edits, which is a
    sentence split into parts. And the letters of one held whole inside the other's, which is a part
    cut at a letter rather than a word.
    """
    if isinstance(line, list):
        return light_rewrite_of(line, fitted)
    tokens = sentence_tokens(line)
    if not tokens:
        return None
    return light_rewrite_of(tokens, fitted, clauses=clauses_of(line))


# Where a clause ends, read on the line as written: a comma, a semicolon, a colon, or a joining word.
REWRITE_CLAUSE_BREAK = re.compile(r'[,;:]|(?<![\w-])(?:and|but|so|which|because|while|whereas|where|or)(?![\w-])', re.I)
# Up to this many clauses are tried in every order; past it the whole is tried as written and rotated.
CLAUSES_PERMUTED = 4


def clauses_of(line):
    """The line as its clauses, each a list of words as compared, in the order written."""
    parts = [sentence_tokens(part) for part in REWRITE_CLAUSE_BREAK.split(line)]
    parts = [comparable(part) for part in parts if part]
    return parts if len(parts) > 1 else []


def arrangements(tokens, clauses):
    """The line's words as written, then with its clauses in every other order."""
    yield tokens
    if not clauses:
        return
    import itertools
    seen = {tuple(tokens)}
    orders = itertools.permutations(range(len(clauses))) if len(clauses) <= CLAUSES_PERMUTED else \
        ((*range(i, len(clauses)), *range(i)) for i in range(1, len(clauses)))
    for order in orders:
        arranged = [t for i in order for t in clauses[i]]
        if tuple(arranged) not in seen:
            seen.add(tuple(arranged))
            yield arranged


def edits_along(a, b, limit):
    """The fewest words substituted, inserted, deleted or swapped with a neighbour to turn `a` into
    `b`, counted along the two sequences, or `limit + 1` once it is past the limit.

    Where every cell of one step of the table is past the limit the answer is decided rather than
    abandoned: every alignment passes through that step and costs at least that much, so the
    distance is past the limit too.
    """
    if abs(len(a) - len(b)) > limit:
        return limit + 1
    previous2 = None
    previous = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        current = [i] + [0] * len(b)
        for j in range(1, len(b) + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            best = min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                best = min(best, previous2[j - 2] + 1)
            current[j] = best
        if min(current) > limit:
            return limit + 1
        previous2, previous = previous, current
    return previous[len(b)]


def swaps_among(have, want, budget):
    """The fewest swaps of two positions turning `have` into `want`, both short lists of the words at
    the positions where two arrangements differ, or None past `budget`. Two arrangements of one bag
    differ at no more than two positions per swap, so with a budget of two there are at most four
    positions here and the pairings among them are a constant to try; a swap of a position where the
    two already agree can only be undone by another, so none is tried."""
    if len(have) > 2 * budget:
        return None
    frontier = [tuple(have)]
    seen = {tuple(have)}
    target = tuple(want)
    for depth in range(budget + 1):
        if target in frontier:
            return depth
        if depth == budget:
            return None
        grown = []
        for state in frontier:
            for i in range(len(state)):
                for j in range(i + 1, len(state)):
                    if state[i] == state[j]:
                        continue
                    swapped = list(state)
                    swapped[i], swapped[j] = swapped[j], swapped[i]
                    swapped = tuple(swapped)
                    if swapped not in seen:
                        seen.add(swapped)
                        grown.append(swapped)
        frontier = grown
    return None


def swaps_between(a, b, budget):
    """The fewest swaps of two words, wherever they sit, turning `a` into `b`, two arrangements of
    the same length, or None past `budget`."""
    if len(a) != len(b):
        return None
    apart = [i for i in range(len(a)) if a[i] != b[i]]
    return swaps_among([a[i] for i in apart], [b[i] for i in apart], budget)


def one_edit_and_swaps(a, b, budget):
    """Whether `a` becomes `b` by one word substituted, inserted or deleted and then up to `budget`
    swaps of two words of the sentence. Gives the swaps spent, or None.

    Two words of the sentence swapped: the swap moves words the recorded sentence has, so where a
    word is inserted the swap is between two of the others, and a swap that moves the inserted word
    is not read as one edit. It is a word moved across the sentence beside a word inserted, which is
    three edits counted along the sentence, and it is not seen.
    """
    if len(a) == len(b):
        # One word substituted, at a position where the two differ, for a word that sits at one of
        # those positions in the other; then the positions still differing are a swap or nothing.
        apart = [i for i in range(len(a)) if a[i] != b[i]]
        if len(apart) > 1 + 2 * budget:
            return None
        best = None
        for at in apart:
            for word in {b[i] for i in apart}:
                if word == a[at]:
                    continue
                changed = list(a)
                changed[at] = word
                still = [i for i in apart if changed[i] != b[i]]
                spent = swaps_among([changed[i] for i in still], [b[i] for i in still], budget)
                if spent is not None and (best is None or spent < best):
                    best = spent
        return best
    longer, shorter = (a, b) if len(a) > len(b) else (b, a)
    if len(longer) != len(shorter) + 1:
        return None
    # One word taken out of the longer at position `at`; before it the two are read in step and
    # after it the longer is one ahead. The positions where they still differ are found once for
    # each half and counted per `at` with two pointers, so the whole sweep is linear.
    forward = [i for i in range(len(shorter)) if longer[i] != shorter[i]]
    backward = [i for i in range(1, len(longer)) if longer[i] != shorter[i - 1]]
    best = None
    ahead = 0
    behind = 0
    for at in range(len(longer)):
        while ahead < len(forward) and forward[ahead] < at:
            ahead += 1
        while behind < len(backward) and backward[behind] <= at:
            behind += 1
        if ahead > 2 * budget:
            break
        if ahead + (len(backward) - behind) > 2 * budget:
            continue
        positions = forward[:ahead] + [i - 1 for i in backward[behind:]]
        have = [longer[i] if i < at else longer[i + 1] for i in positions]
        want = [shorter[i] for i in positions]
        spent = swaps_among(have, want, budget)
        if spent is not None and (best is None or spent < best):
            best = spent
    return best


def edits_within(a, b, limit):
    """The fewest word edits turning `a` into `b`, or `limit + 1` once past the limit, where an edit
    is a word substituted, inserted or deleted, or two words of the sentence swapped, whether or not
    they are neighbours.

    Counted along the sentence first, which reads a swap of neighbours as one edit and a swap across
    a gap as two substitutions. Where that is past the limit, the decision is taken in two parts the
    file already computes: the bags of words say how many edits have to be substitutions, insertions
    or deletions, because a swap leaves the bag as it was, and what is left of the limit goes on
    swaps, found among the positions where the two arrangements still differ. With a limit of two
    that is the whole bag as it is and up to two swaps, or one word changed and one swap. A limit
    above two never arises, `EDITS_IN_A_LONG_SENTENCE`, and two words changed with a swap beside
    them is not read.
    """
    along = edits_along(a, b, limit)
    if along <= limit or limit < 1:
        return along
    apart = edits_between(collections.Counter(a), collections.Counter(b))
    if apart >= limit:
        # Every edit has to change the bag, so none is a swap, and the count along the sentence has
        # already decided that.
        return limit + 1
    budget = limit - apart
    if apart == 0:
        spent = swaps_between(a, b, budget)
        return spent if spent is not None else limit + 1
    if apart == 1:
        spent = one_edit_and_swaps(a, b, budget)
        return 1 + spent if spent is not None else limit + 1
    return limit + 1


def light_rewrite_of(tokens, fitted, whole_only=False, clauses=()):
    """With `whole_only`, only a reading that takes the whole of `tokens` as the sentence counts: the
    print, the letters, or the words within the edits. Used for lines joined together, which are
    parts of one sentence or nothing, so a sentence held inside the join proves nothing about the
    parts. `clauses` is the line split at its clause breaks, tried in every order."""
    digest = print_of(tokens)
    tokens = comparable(tokens)
    letters = ''.join(tokens)
    bag = collections.Counter(tokens)
    for f in fitted:
        if f.digest == digest:
            return f, 'the same words'
        if not f.tokens:
            continue
        if letters == f.letters:
            return f, 'the same letters'
        k = f.edits
        shared = sum((bag & f.bag).values())
        # The bag is the cheap half: no order of the words can be within k edits along the sentence
        # unless the bags are within k, so most recorded sentences are passed over here.
        if shared >= len(f.tokens) - k and edits_between(bag, f.bag) <= k:
            for arranged in arrangements(tokens, clauses):
                edits = edits_within(arranged, f.tokens, k)
                if edits <= k:
                    if edits == 0:
                        return f, 'the same words' if arranged == tokens else 'the same words with the clauses in another order'
                    return f, f'the same words within {edits} edits' + ('' if arranged == tokens else ', with the clauses in another order')
        if whole_only:
            continue
        if len(tokens) > len(f.tokens) and shared >= len(f.tokens) - k:
            for arranged in arrangements(tokens, clauses):
                for size in range(max(1, len(f.tokens) - k), len(f.tokens) + k + 1):
                    for at in range(len(arranged) - size + 1):
                        if edits_within(arranged[at:at + size], f.tokens, k) <= k:
                            return f, 'held whole inside the line'
        if len(letters) >= FEWEST_LETTERS and len(tokens) < len(f.tokens) and shared >= len(tokens) - k:
            for size in range(max(1, len(tokens) - k), min(len(f.tokens), len(tokens) + k) + 1):
                for at in range(len(f.tokens) - size + 1):
                    if edits_within(tokens, f.tokens[at:at + size], k) <= k:
                        return f, 'a part of it'
        shorter = min(len(letters), len(f.letters))
        if shorter >= FEWEST_LETTERS and (letters in f.letters or f.letters in letters):
            return f, 'the same letters, held whole'
    return None


def marked(text):
    """The sentences of a set, each with what it is meant to do.

    A line opening `- ` has to be refused and a line opening `+ ` has to pass. `~ ` is a line the set
    excluded by name with its reason above it, and `#` is a comment. Anything else is not a set.
    """
    wanted = []
    for number, line in enumerate(text.splitlines(), 1):
        body = line.strip()
        if not body or body.startswith('#') or body.startswith('~'):
            continue
        if body[:2] not in ('- ', '+ '):
            raise Unreadable(f'line {number} opens with neither "- " nor "+ " nor "~ ": {body[:60]}')
        wanted.append((body[0] == '-', body[2:].strip(), number))
    if not wanted:
        raise Unreadable('no sentence in it is marked to be refused or to pass, so there is nothing '
                         'to score')
    return wanted


def refusals(sentence, policy):
    """Everything the tree check would refuse a sentence for: the rules, and the walk over its figures.

    Until 2026-09-17 a set was scored by the rules alone, so a figure the register does not hold, or holds
    as something else, passed `--score` while the same sentence on a surface was refused. A score that
    reads less than the check it scores is a number about a different check.
    """
    return judge(sentence, policy) + unclaimed([('the set', sentence)], policy, None, [])[0]


def score(path, policy):
    """What this file makes of a set it has not been fitted to, and a refusal where it has.

    Exit 2 where the set is already in this file, by the list or by the sentences it holds, because a
    number taken on material this file was shaped around is not a measurement and reads exactly like
    one.
    """
    file = Path(path)
    if not file.is_file():
        raise Unreadable(f'{path} is not there')
    raw = file.read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    known = fitted_sets()
    seen = known.get(sha)

    if seen and seen['state'] == 'fitted':
        print(f'policy sentences: {file.name} is {seen["name"]} in {FITTED.name}, fitted on '
              f'{seen["frozen"]}. Its misses are rules in this file, so a number taken on it now '
              f'measures nothing. Freeze a set this file has not been shaped around.', file=sys.stderr)
        return 2

    text = raw.decode('utf-8')

    # The sentences a fitted set holds, whatever file they are in now and however they are written,
    # and the seeds and honest sentences of this file with them: recorded material is recorded
    # material whichever list it came from. Read before the set is parsed, so a fitted set whose
    # markers were changed into something this cannot parse is still named.
    try:
        fitted = recorded_sentences(known)
    except Unreadable as e:
        print(f'policy sentences: {e}', file=sys.stderr)
        return 2
    lines = [(number, line.strip(), sentence_tokens(line)) for number, line in enumerate(text.splitlines(), 1)
             if sentence_tokens(line)]
    counted = [(number, line) for number, line, _ in lines if line[:1] not in ('~', '+')]
    from_fitted = []
    matched = set()
    for number, line, tokens in lines:
        found = light_rewrite_of(tokens, fitted, clauses=clauses_of(line))
        if found:
            f, how = found
            from_fitted.append((number, line, sorted(f.names), how))
            matched.add(number)
    # A sentence split into parts that sit on adjacent lines in order, each part too short to be
    # compared on its own: the lines are read joined, two and then three at a time.
    for i in range(len(lines)):
        for span in (2, 3):
            group = lines[i:i + span]
            if len(group) < span or all(n in matched for n, _, _ in group):
                continue
            joined = [t for _, _, tokens in group for t in tokens]
            found = light_rewrite_of(joined, fitted, whole_only=True)
            if found:
                f, how = found
                for number, line, _ in group:
                    if number not in matched:
                        from_fitted.append((number, line, sorted(f.names), f'{how}, as one sentence with the lines beside it'))
                        matched.add(number)
    from_fitted.sort()
    in_count = [(number, line, names, how) for number, line, names, how in from_fitted
                if line[:1] not in ('~', '+')]
    # Each match is named and taken out of the count, a line marked to pass among them too. Two
    # people quoting one document land on the same words, and two of the three overlaps on
    # 2026-09-16 were the rule about NTS never being portable evidence and the one about a private
    # root being admissible and never presumed, both quoted from the source; so the line is set aside
    # rather than the set being thrown away, which keeps the number honest without wasting a cold
    # set on a coincidence.
    for number, line, names, how in from_fitted:
        print(f'policy sentences: line {number} is a sentence of {", ".join(names)}, which is recorded '
              f'here, {how}, and is out of the count: "{line[:90]}"')
    residue = len(counted) - len(in_count)
    if residue < SENTENCE_FLOOR:
        sets = sorted({name for _, _, names, _ in in_count for name in names})
        if in_count:
            print(f'policy sentences: {len(in_count)} of the {len(counted)} sentences to be refused in {file.name} are '
                  f'sentences of {", ".join(sets)}, recorded here, whatever this file is called and '
                  f'however they are written, and {residue} {"is" if residue == 1 else "are"} left, under the '
                  f'floor of {SENTENCE_FLOOR} this file scores on. A number taken on what is left would '
                  f'measure nothing. Freeze a set this file has not been shaped around.', file=sys.stderr)
        else:
            print(f'policy sentences: {file.name} holds {residue} sentences to be refused, under the floor of '
                  f'{SENTENCE_FLOOR} this file scores on, so there is nothing here to score', file=sys.stderr)
        return 2

    wanted = marked(text)
    out_of_count = {number for number, _, _, _ in from_fitted}
    wanted = [(refuse, s, n) for refuse, s, n in wanted if n not in out_of_count]

    if seen:
        print(f'policy sentences: {file.name} is {seen["name"]}, which has scored this file before, '
              f'on {seen["frozen"]}. It is not cold and the number below is weaker than a first '
              f'reading of it.')

    missed = []
    right = 0
    for refuse, sentence, number in wanted:
        faults = refusals(sentence, policy)
        if bool(faults) == refuse:
            right += 1
        else:
            missed.append((refuse, number, sentence, faults))

    for refuse, number, sentence, faults in missed:
        if refuse:
            print(f'policy sentences: line {number} passed and had to be refused: "{sentence[:150]}"',
                  file=sys.stderr)
        else:
            print(f'policy sentences: line {number} was refused and is honest ({"; ".join(faults)}): '
                  f'"{sentence[:150]}"', file=sys.stderr)

    refusable = sum(1 for refuse, _, _ in wanted if refuse)
    caught = sum(1 for refuse, sentence, _ in wanted if refuse and refusals(sentence, policy))
    print(f'policy sentences: {caught} of {refusable} refused, {right} of {len(wanted)} right, on a residue of '
          f'{residue} of {len(counted)} sentences to be refused ({len(in_count)} recorded here and out of the '
          f'count), on {file.name} at sha256 {sha[:16]}. Record that sha in {FITTED.name} before this file '
          f'is changed on the strength of it.')
    return 0 if not missed else 1


def the_score_refuses_a_fitted_set(policy):
    """A set this file has already been shaped around cannot be used to say how good it is.

    Watched rather than assumed, on material built here: a set carrying one of this file's own seeds,
    and a set whose sha is in the manifest as fitted. Both have to come back 2, which is this file's
    code for nothing having been checked, and never 0 or 1 with a number beside it.
    """
    import tempfile

    faults = []
    known = fitted_sets()
    if not known:
        faults.append(f'{FITTED.name} names no set at all, so nothing is being refused')
    if not any(s['state'] == 'fitted' for s in known.values()):
        faults.append(f'{FITTED.name} marks nothing fitted, and every set this file was built '
                      f'around is fitted')

    print('policy sentences: the two refusals below are this check watching --score turn away a set '
          'it has been fitted to. They are what a green run looks like.')
    work = Path(tempfile.mkdtemp(prefix='tw-score-'))
    try:
        seed = SEEDS[0][1].strip()
        carries = work / 'carries-a-seed.txt'
        carries.write_text(NEWLINE.join([
            '# a set with one sentence taken out of this file',
            f'- {seed}',
            '- TimeWitness is accurate to the nanosecond.',
            '+ The bound is what the receipt carries, beside the reading.',
            '',
        ]), encoding='utf-8')
        if score(str(carries), policy) != 2:
            faults.append('a set holding a seed of this file was scored rather than refused')

        # The manifest's own half, on a set that is fitted and holds no seed word for word.
        fitted_sha = next(sha for sha, s in known.items() if s['state'] == 'fitted')
        original = FITTED.read_bytes()
        stand_in = work / 'a-fitted-set.txt'
        stand_in.write_text(NEWLINE.join([
            '# a set standing in for one this file has been shaped around',
            '- TimeWitness is accurate to the nanosecond.',
            '+ The bound is what the receipt carries, beside the reading.',
            '',
        ]), encoding='utf-8')
        import hashlib as _h
        sha = _h.sha256(stand_in.read_bytes()).hexdigest()
        try:
            row = f'{sha}  fitted  2026-09-16  a-fitted-set.txt' + NEWLINE
            FITTED.write_bytes(original + row.encode())
            if score(str(stand_in), policy) != 2:
                faults.append('a set named fitted in the manifest was scored rather than refused')
        finally:
            FITTED.write_bytes(original)
        if not fitted_sha:
            faults.append('the manifest holds no fitted sha to read')
    finally:
        shutil.rmtree(work, ignore_errors=True)
    return faults


def the_score_refuses_a_fitted_set_however_it_is_written(policy):
    """A fitted set is refused by the sentences it holds, not by the bytes of its file.

    Until 2026-09-17 the list knew a fitted set only by the sha256 of its file, so one comment line
    appended to it gave a different sha and the set scored 45 of 45; by that afternoon a print of the
    words was in and one space deleted per line, every item numbered, a trailing clause and two
    sentences joined each gave a fresh print. Each walk-round here is one member of the closed list
    of light rewrites, built on a stand-in set recorded as fitted for the length of the check, and
    each has to come back 2 with the stand-in named. The list entry is deleted in one of them and the
    sentences recorded for it are not, which is the walk-round a list alone cannot see. Every member
    of `LIGHT_REWRITES` has to be covered by some walk, and the swaps are generated at their
    distances rather than typed, so a swap across a gap is what the walk says it is.
    """
    import contextlib
    import io
    import tempfile

    faults = []
    name = 'a-fitted-set-walked-round.txt'
    body = [
        '- TimeWitness keeps every build on true UTC to the nanosecond.',
        '- The receipt proves the deploy was blocked when the clock was wrong.',
        '- A refusal blocks the pipeline outright.',
        '+ The bound is what the receipt carries, beside the reading.',
        '+ A refusal records that the agent declined to sign.',
    ]
    text = NEWLINE.join(['# a stand-in for a set this file has been shaped around'] + body + [''])
    # A line recorded nowhere, for the walks whose other lines are all that is left to score; and
    # five of them, for the sets outside the list, which have to reach the floor to score at all.
    FRESH = '- Nothing written on this particular line is recorded anywhere in this file.'
    FRESH_FIVE = [
        FRESH,
        '- The kettle in the corner of the office boils in about the time a long test suite takes to link.',
        '- The car park has forty spaces and the lift has been out of order since the spring.',
        '- A footnote about the weather on the day of the demo says nothing about any clock anywhere.',
        '- Whoever reads this far will find only a remark about the length of the corridor outside.',
    ]
    work = Path(tempfile.mkdtemp(prefix='tw-walk-'))
    manifest = FITTED.read_bytes()
    recorded = FITTED_SENTENCES.read_bytes() if FITTED_SENTENCES.is_file() else None

    def rewritten(first, second, third=None):
        return NEWLINE.join(['# rewritten', first, second, third or body[2]] + body[3:] + [''])

    def words(line):
        return line[2:].split()

    def joined(parts):
        return '- ' + ' '.join(parts)

    def swapped(line, i, j):
        """The line with the words at positions `i` and `j` swapped, `j - i` being the gap."""
        out = words(line)
        out[i], out[j] = out[j], out[i]
        return joined(out)

    def replaced(line, old, new):
        return joined([new if w == old else w for w in words(line)])

    def without(line, word):
        out = words(line)
        out.remove(word)
        return joined(out)

    def inserted(line, at, word):
        out = words(line)
        out.insert(at, word)
        return joined(out)

    # Each walk: the file name, its content, whether the list entry is dropped, and the members of
    # the closed list it covers.
    walks = {
        'a comment line appended': (name, text + '# one more line' + NEWLINE, False, ()),
        'the sentences reordered': (name, NEWLINE.join(['# reordered'] + body[::-1] + ['']), False, ('lines reordered',)),
        'the file renamed and one space doubled': ('renamed.txt', text.replace('keeps every', 'keeps  every'), False, ('whitespace',)),
        'one space deleted in every sentence': (name, text.replace('the nanosecond', 'thenanosecond').replace('was wrong', 'waswrong'), False, ('whitespace',)),
        'every item numbered': (name, rewritten('- 1) ' + body[0][2:], '- 2) ' + body[1][2:]), False, ('numbering',)),
        'a trailing clause on every sentence': (name, text.replace('nanosecond.', 'nanosecond, as it says.').replace('wrong.', 'wrong, as it says.'), False, ('held whole inside a longer line',)),
        'two sentences joined into one': (name, NEWLINE.join(['# joined', body[0] + ' ' + body[1][2:], body[2]] + body[3:] + ['']), False, ('held whole inside a longer line',)),
        'a sentence cut in two': (name, NEWLINE.join(['# cut', '- TimeWitness keeps every build', '- on true UTC to the nanosecond.', FRESH] + body[3:] + ['']), False, ('split into parts on adjacent lines',)),
        'a sentence cut in two with the parts apart': (name, NEWLINE.join(['# cut apart', '- on true UTC to the nanosecond.', FRESH, '- TimeWitness keeps every build'] + body[3:] + ['']), False, ('a part of at least the fewest letters',)),
        'a sentence cut in two with a word changed in each part': (name, NEWLINE.join(['# cut and changed', '- on true UTC to a nanosecond.', FRESH, '- TimeWitness holds every build'] + body[3:] + ['']), False, ('a part of at least the fewest letters',)),
        # Until 2026-09-18 this walk moved a phrase with no clause break, "to the nanosecond on true
        # UTC", which is outside the list, and it stayed green because the set was refused on its
        # other line; the walk now reorders at the comma, which is the member it stands for.
        'the clauses in another order': (name, rewritten('- On true UTC to the nanosecond, TimeWitness keeps every build.', body[1]), False, ('clauses reordered',)),
        'a word swapped for a synonym': (name, rewritten(body[0].replace('keeps', 'holds'), body[1].replace('proves', 'shows')), False, ('a word substituted',)),
        'the articles deleted': (name, rewritten('- TimeWitness keeps every build on true UTC to nanosecond.', '- Receipt proves deploy was blocked when clock was wrong.'), False, ('a word deleted',)),
        'a look-alike letter in every sentence': (name, text.replace('a', '\u0430'), False, ('look-alike letters',)),
        'a zero-width space inside a word': (name, text.replace('nanosecond', 'nano\u200bsecond').replace('blocked', 'blo\u200bcked'), False, ('marks and invisible characters',)),
        'a soft hyphen inside a word': (name, text.replace('nanosecond', 'nano\u00adsecond').replace('blocked', 'blo\u00adcked'), False, ('marks and invisible characters',)),
        'a combining mark on a letter': (name, text.replace('nanosecond', 'nanose\u0301cond').replace('blocked', 'blo\u0301cked'), False, ('marks and invisible characters',)),
        'the case changed throughout': (name, text.upper().replace('# A STAND-IN', '# a stand-in'), False, ('case',)),
        'the full stops gone and the commas in': (name, text.replace('nanosecond.', 'nanosecond,').replace('wrong.', 'wrong').replace('outright.', 'outright;'), False, ('punctuation',)),
        'wrapped in markup': (name, rewritten('- **TimeWitness** keeps _every_ build on `true UTC` to the nanosecond.', '- > The receipt proves the deploy was blocked when the clock was wrong.'), False, ('markup',)),
        'padded with three hundred excluded lines': (name, text + NEWLINE.join(f'~ excluded line {i}' for i in range(300)) + NEWLINE, False, ()),
        'its list entry deleted': (name, text, True, ()),
        # The closed list of light rewrites, one walk each, added on the evening of 2026-09-17.
        'two words changed in a sentence of ten words or more': (name, rewritten(
            '- TimeWitness holds every release on true UTC to the nanosecond.',
            '- The voucher proves the deploy was halted when the clock was wrong.'), False, ('a word substituted',)),
        'a word inserted and two neighbours swapped': (name, rewritten(
            '- TimeWitness really keeps build every on true UTC to the nanosecond.',
            '- The receipt proves the deploy was blocked when clock the was really wrong.'), False, ('a word inserted', 'two neighbouring words swapped')),
        'a negation added': (name, rewritten(
            '- TimeWitness never keeps every build on true UTC to the nanosecond.',
            '- The receipt proves the deploy was not blocked when the clock was wrong.'), False, ('a negation included',)),
        'the clauses reordered and a word changed': (name, rewritten(
            '- On true UTC to the nanosecond, TimeWitness holds every build.',
            '- When the clock was wrong, the voucher proves the deploy was blocked.'), False, ('clauses reordered', 'a word substituted')),
        'the rewritten sentence held inside a longer line': (name, rewritten(
            '- As the brochure says, TimeWitness holds every build on true UTC to the nanosecond, and more besides.',
            '- In short, the voucher proves the deploy was blocked when the clock was wrong, which is the offer.'), False, ('held whole inside a longer line',)),
        'three sentences merged on one line': (name, NEWLINE.join(['# merged',
            '- ' + body[0][2:] + ' ' + body[1][2:] + ' ' + body[3][2:]] + ['']), False, ('three sentences merged on one line',)),
        'split into parts under twenty letters on adjacent lines': (name, NEWLINE.join(['# split',
            '- TimeWitness keeps', '- every build on true', '- UTC to the nanosecond.', FRESH] + body[3:] + ['']), False, ('split into parts on adjacent lines',)),
        'a seed of this file one word changed, marked to be refused': (name, NEWLINE.join(['# seeds'] + [
            '- ' + ' '.join(('this' if w == 'the' else w) for w in seed.split()) for _, seed in SEEDS[:4]] + body[3:] + ['']), False, ('the seeds, one word changed',)),
        'the honest sentences of this file marked to be refused': (name, NEWLINE.join(['# honest'] + [
            '- ' + honest for honest in HONEST[:4]] + body[3:] + ['']), False, ('the honest sentences, marked to be refused',)),
        'a digit drawn for a letter in every word it fits': (name, rewritten(
            '- TimeWitne55 keep5 ev3ry bui1d 0n tru3 UTC t0 th3 nan0sec0nd.',
            '- Th3 rec3ipt pr0ves the dep10y wa5 b10cked when the c10ck wa5 wr0ng.'), False, ('a digit drawn for a letter',)),
        'a letter doubled in every word': (name, rewritten(
            '- Timmewitness keeeps evvery buiild on truue UTTC to thhe nannosecond.',
            '- Thhe receeipt provves thhe depploy waas bloocked whhen thhe cloock waas wroong.'), False, ('a letter doubled',)),
        # Two words swapped across a gap, generated at the distance each walk names, added
        # 2026-09-18 after the walk above, with neighbours only, stayed green while the code charged
        # a swap across a gap as two substitutions and a third edit beside it went unseen.
        'two words swapped across a gap of two': (name, rewritten(swapped(body[0], 2, 4), swapped(body[1], 3, 5)), False, ('two words swapped across a gap of two',)),
        'two words swapped across a gap of three': (name, rewritten(swapped(body[0], 1, 4), swapped(body[1], 4, 7)), False, ('two words swapped across a gap of three',)),
        'two words swapped across a gap of five': (name, rewritten(swapped(body[0], 2, 7), swapped(body[1], 1, 6)), False, ('two words swapped across a gap of five',)),
        'a swap across a gap of three and a word substituted': (name, rewritten(
            replaced(swapped(body[0], 1, 4), 'keeps', 'holds'), replaced(swapped(body[1], 4, 7), 'receipt', 'voucher')), False, ('a swap across a gap with a word substituted',)),
        'a swap across a gap of four and a word deleted': (name, rewritten(
            without(swapped(body[0], 2, 6), 'the'), without(swapped(body[1], 3, 7), 'the')), False, ('a swap across a gap with a word deleted',)),
        'a swap across a gap of five and a word inserted': (name, rewritten(
            inserted(swapped(body[0], 2, 7), 5, 'plainly'), inserted(swapped(body[1], 1, 6), 9, 'plainly')), False, ('a swap across a gap with a word inserted',)),
        'two swaps across gaps of two and four': (name, rewritten(
            swapped(swapped(body[0], 1, 3), 5, 9), swapped(swapped(body[1], 2, 4), 6, 10)), False, ('two swaps across gaps',)),
        'a swap across a gap of two in a sentence of five to nine words': (name, rewritten(body[0], body[1], swapped(body[2], 1, 3)), False, ('a swap across a gap in a sentence of five to nine words',)),
    }
    covered = {member for _, _, _, members in walks.values() for member in members}
    for member in LIGHT_REWRITES:
        if member not in covered:
            faults.append(f'the light-rewrite list has "{member}" and no walk covers it')
    # Outside the list, so not a match by name: three words changed in a sentence of ten, and a
    # fragment under twenty letters. Each has to score, with no line named as recorded material,
    # so each carries five fresh lines to reach the floor a score needs.
    outside = {
        'three words changed in a sentence of ten words': NEWLINE.join(['# outside',
            '- TimeWitness holds every release on true UTC to this nanosecond.',
            '- The voucher shows the deploy was halted when the clock was wrong.'] + FRESH_FIVE + body[3:] + ['']),
        'two words changed in a sentence of five to nine words': NEWLINE.join(['# short',
            '- Our voucher shows the deploy blocked.',
            '- The voucher shows the deploy was halted when the clock was wrong.'] + FRESH_FIVE + body[3:] + ['']),
        'a fragment under twenty letters': NEWLINE.join(['# fragment',
            '- Keeps every build.',
            '- The voucher shows the deploy was halted when the clock was wrong.'] + FRESH_FIVE + body[3:] + ['']),
        'a swap across a gap and two words substituted, three edits': NEWLINE.join(['# three edits',
            replaced(replaced(swapped(body[0], 1, 4), 'keeps', 'holds'), 'build', 'release'),
            replaced(replaced(swapped(body[1], 4, 7), 'receipt', 'voucher'), 'blocked', 'halted')] + FRESH_FIVE + body[3:] + ['']),
        'a swap across a gap in a short sentence and a word substituted, two edits': NEWLINE.join(['# short and two',
            replaced(swapped(body[2], 1, 3), 'blocks', 'halts'),
            '- The voucher shows the deploy was halted when the clock was wrong.'] + FRESH_FIVE + body[3:] + ['']),
    }
    try:
        original = work / name
        original.write_text(text, encoding='utf-8')
        sha = hashlib.sha256(original.read_bytes()).hexdigest()
        FITTED.write_bytes(manifest + f'{sha}  fitted  2026-09-17  {name}{NEWLINE}'.encode())
        rows = ''.join(f'{digest}  {name}  {" ".join(tokens)}{NEWLINE}' for digest, tokens in sentence_prints_of(text))
        FITTED_SENTENCES.write_bytes((recorded or b'') + rows.encode())

        for walk, (file_name, content, drop_row, _) in walks.items():
            target = work / file_name
            target.write_text(content, encoding='utf-8')
            # The list entry is put back before every walk, because the walk that deletes it
            # would otherwise leave every walk after it refused for the missing entry, which
            # names the set and reads as a pass.
            FITTED.write_bytes(manifest if drop_row else manifest + f'{sha}  fitted  2026-09-17  {name}{NEWLINE}'.encode())
            said = io.StringIO()
            with contextlib.redirect_stdout(said), contextlib.redirect_stderr(said):
                try:
                    code = score(str(target), policy)
                except Unreadable as e:
                    print(e)
                    code = 2
            if code != 2 or name not in said.getvalue():
                faults.append(f'a fitted set with {walk} came back {code} rather than 2 with the set named')
            # Exit 2 with the set named is not enough on its own: a stand-in of three lines is under
            # the floor whether or not its lines were seen, and the floor refusal names the file.
            # Every line marked to be refused that is a rewrite has to have been named as recorded
            # material, line by line, or the walk watched the floor and not the matching.
            if drop_row:
                if 'has sentences recorded' not in said.getvalue():
                    faults.append(f'a fitted set with {walk} was not refused for its sentences outliving its entry')
                continue
            for number, line in enumerate(content.splitlines(), 1):
                if line.startswith('- ') and line not in FRESH_FIVE and not re.search(rf'line {number} is a sentence of', said.getvalue()):
                    faults.append(f'a fitted set with {walk} had line {number} unnamed, so the set was refused on '
                                  f'the floor and not on what it holds: "{line[:70]}"')
        # The last walk above dropped the stand-in's list entry; put it back for these.
        FITTED.write_bytes(manifest + f'{sha}  fitted  2026-09-17  {name}{NEWLINE}'.encode())
        for walk, content in outside.items():
            target = work / 'outside-the-list.txt'
            target.write_text(content, encoding='utf-8')
            said = io.StringIO()
            with contextlib.redirect_stdout(said), contextlib.redirect_stderr(said):
                try:
                    code = score(str(target), policy)
                except Unreadable as e:
                    print(e)
                    code = 2
            first = content.splitlines()[1]
            if code == 2 or ('line 2 is' in said.getvalue()):
                faults.append(f'a set with {walk} came back {code}, or its first line was named as '
                              f'recorded material, and it is outside the list: "{first[:70]}"')
        # The residue is what is scored: five fresh lines beside one recorded verbatim score on the
        # five, the score line says so, and the recorded line is out of the count rather than in it.
        target = work / 'one-recorded-five-fresh.txt'
        target.write_text(NEWLINE.join(['# one recorded', body[0]] + FRESH_FIVE + body[3:] + ['']), encoding='utf-8')
        said = io.StringIO()
        with contextlib.redirect_stdout(said), contextlib.redirect_stderr(said):
            code = score(str(target), policy)
        if code == 2 or not re.search(r'\d+ of 5 refused, \d+ of 5 right, on a residue of 5 of 6 sentences to be refused \(1 recorded here and out of the count\)', said.getvalue()):
            faults.append(f'a set of five fresh lines and one recorded came back {code} without a residue of 5 of 6 on its score line')
    finally:
        FITTED.write_bytes(manifest)
        if recorded is None:
            FITTED_SENTENCES.unlink(missing_ok=True)
        else:
            FITTED_SENTENCES.write_bytes(recorded)
        shutil.rmtree(work, ignore_errors=True)
    return faults


def another_tree(tree, pattern, policy):
    """The claim rules over the surfaces of a tree that is not this one, as (sentences read, files
    read, problems).

    The app's front page told every reader that the outside signatures pin when a receipt was signed,
    for nine days, while this file held the site and the README to the opposite. Nothing read the
    app. The rules are read from here rather than copied there, which is how the price rules already
    reach it, so there is still one copy of them.

    Only the claims are held. The figures are not, because what answers a figure is a register of
    this tree's surfaces, and a tree it has never heard of would be refused on every number it holds,
    which is a check nobody keeps switched on. The ceiling rule is held, because it asks only whether
    a surface quoting the committed receipt also says what that receipt was signed under.
    """
    base = Path(tree).resolve()
    if not base.is_dir():
        raise Unreadable(f'{tree} is not a directory')
    # What a build or a tool leaves behind is not a surface: a dot folder, dependencies, build output.
    skip = {'node_modules', 'out', 'target'}
    files = sorted(p for p in base.rglob('*')
                   if p.is_file()
                   and not any(part.startswith('.') or part in skip for part in p.relative_to(base).parts[:-1])
                   and pattern.search(p.relative_to(base).as_posix()))
    # Every tree this is pointed at has a README and at least one page of content, so fewer than two
    # files means the pattern is wrong rather than that the tree has nothing to say.
    if len(files) < 2:
        raise Unreadable(f'the pattern found {len(files)} surfaces in {tree}, so it is not reading the tree')
    read_from, _ = surfaces([str(p) for p in files], None, 1)
    names = {str(p): p.relative_to(base).as_posix() for p in files}
    def named(where):
        for tag in LEGAL_ONLY:
            if where.endswith(tag):
                return names.get(where[:-len(tag)], where[:-len(tag)]) + tag
        return names.get(where, where)
    read_from = [(named(where), sentence) for where, sentence in read_from]
    # A tree's surfaces are named to the legal weight rule with `tree:` before their path, so an
    # entry for this repository's README is not an entry for the README of a tree it reads.
    problems = contradictions(read_from, policy, None, lambda where: 'tree:' + where)
    split = [(where, piece) for where, unit in not_above_the_list(read_from) for piece in pieces(unit)]
    problems += the_ceiling_is_stated(split)
    return len(split), len(files), problems


def a_tree_elsewhere_is_read(policy):
    """Whether --tree reads the tree it is given and refuses the sentence the app actually served.

    A tree made up here with a README and a page of content: once honest, where it has to pass, and
    once with the app's own sentence of 2026-09-14 planted in the page, where it has to be refused
    and the refusal has to name the page rather than the README."""
    import tempfile
    page = {'free': {'body': 'Anyone can verify a receipt, free and with no account. The outside signatures in a '
                             'receipt can be checked without trusting either party. They say when the thing it stamps '
                             'existed, and only a witness over the receipt\'s own signature says when it was signed.'}}
    planted = {'free': {'body': 'Anyone can verify a receipt, free and with no account. The outside signatures in it '
                                'can be checked without trusting either party, and they pin when it was signed.'}}
    faults = []
    with tempfile.TemporaryDirectory() as tmp:
        base = Path(tmp)
        (base / 'content').mkdir()
        (base / 'README.md').write_text('# A made-up tree\n\nIt holds one page and nothing else.\n', encoding='utf-8')
        for what, body, refuse in (('honest', page, False), ('planted', planted, True)):
            (base / 'content' / 'app.json').write_text(json.dumps(body), encoding='utf-8')
            try:
                _, files, problems = another_tree(tmp, re.compile(r'\.(md|txt)$|^content/'), policy)
            except (Unreadable, OSError) as e:
                return [f'--tree could not read a made-up tree: {e}']
            if files != 2:
                faults.append(f'--tree read {files} files of a made-up tree holding 2')
            if refuse and not any(p.startswith('content/app.json: ') for p in problems):
                faults.append('--tree passed the app\'s own sentence of 2026-09-14 planted in a made-up tree')
            if not refuse and problems:
                faults.append(f'--tree refused an honest made-up tree: {problems[0]}')
    return faults


